1: // Tiny synthesized audio engine. No external assets, no network requests.
2: export class AudioEngine {
3:   constructor(settings = {}) {
4:     this.settings = settings;
5:     this.ctx = null;
6:     this.master = null;
7:     this.musicGain = null;
8:     this.sfxGain = null;
9:     this.noiseBuffer = null;
10:     this.musicTimer = null;
11:     this.musicStep = 0;
12:     this.ready = false;
13:   }
