15:   init() {
16:     if (this.ready) return;
17:     const Ctor = window.AudioContext || window.webkitAudioContext;
18:     if (!Ctor) return;
19:     try {
20:       this.ctx = new Ctor();
21:       this.master = this.ctx.createGain();
22:       this.master.gain.value = this.settings.sound === false ? 0 : 0.9;
23:       this.master.connect(this.ctx.destination);
24:       this.sfxGain = this.ctx.createGain();
25:       this.sfxGain.gain.value = 0.62;
26:       this.sfxGain.connect(this.master);
