28:       this.musicGain.gain.value = this.settings.music === false ? 0 : 0.2;
29:       this.musicGain.connect(this.master);
30:       const len = this.ctx.sampleRate * 1.4;
31:       this.noiseBuffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
32:       const data = this.noiseBuffer.getChannelData(0);
33:       for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
34:       this.ready = true;
35:       this.startMusic();
36:     } catch (error) {
37:       console.warn('Audio unavailable', error);
38:     }
39:   }
