46:   syncSettings() {
47:     if (!this.ready) return;
48:     this.master.gain.setTargetAtTime(this.settings.sound === false ? 0 : 0.9, this.ctx.currentTime, 0.04);
49:     this.musicGain.gain.setTargetAtTime(this.settings.music === false ? 0 : 0.2, this.ctx.currentTime, 0.2);
50:   }
51: 
52:   tone({ freq = 220, to = freq, dur = 0.15, type = 'sine', gain = 0.2, delay = 0, filter = null }) {
53:     if (!this.ready || this.settings.sound === false) return;
54:     const t = this.ctx.currentTime + delay;
55:     const osc = this.ctx.createOscillator();
56:     const g = this.ctx.createGain();
57:     osc.type = type;
58:     osc.frequency.setValueAtTime(freq, t);
59:     if (to !== freq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t + dur);
60:     g.gain.setValueAtTime(0.0001, t);
61:     g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.008);
62:     g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
