65:       f.type = filter.type || 'lowpass';
66:       f.frequency.setValueAtTime(filter.freq || 1200, t);
67:       if (filter.to) f.frequency.exponentialRampToValueAtTime(filter.to, t + dur);
68:       osc.connect(f);
69:       f.connect(g);
70:     } else osc.connect(g);
71:     g.connect(this.sfxGain);
72:     osc.start(t);
73:     osc.stop(t + dur + 0.03);
74:   }
