76:   noise({ dur = 0.18, gain = 0.16, type = 'highpass', freq = 900, to = null, delay = 0 }) {
77:     if (!this.ready || this.settings.sound === false) return;
78:     const t = this.ctx.currentTime + delay;
79:     const src = this.ctx.createBufferSource();
