137:       case 'shard':
138:         this.tone({ freq: 1200, to: 1900, dur: 0.055, type: 'triangle', gain: 0.035 });
139:         break;
140:       case 'chest':
141:         this.tone({ freq: 230, to: 300, dur: 0.25, type: 'triangle', gain: 0.1 });
142:         this.tone({ freq: 700, to: 1100, dur: 0.3, type: 'sine', gain: 0.08, delay: 0.16 });
