145:         this.tone({ freq: 330, to: 660, dur: 0.5, type: 'sine', gain: 0.1 });
146:         this.tone({ freq: 495, to: 990, dur: 0.5, type: 'sine', gain: 0.06, delay: 0.08 });
147:         break;
148:       case 'portal':
149:         this.tone({ freq: 180, to: 900, dur: 0.7, type: 'sine', gain: 0.1 });
150:         this.tone({ freq: 300, to: 1400, dur: 0.7, type: 'triangle', gain: 0.05, delay: 0.1 });
151:         break;
152:       case 'boss':
153:         this.tone({ freq: 75, to: 42, dur: 1.1, type: 'sawtooth', gain: 0.15 });
154:         this.tone({ freq: 140, to: 80, dur: 0.9, type: 'square', gain: 0.06 });
155:         this.noise({ dur: 0.8, gain: 0.08, freq: 180, to: 80 });
156:         break;
157:       case 'death':
158:         this.tone({ freq: 300, to: 55, dur: 1.2, type: 'sawtooth', gain: 0.12 });
159:         this.tone({ freq: 150, to: 30, dur: 1.4, type: 'sine', gain: 0.1 });
160:         break;
161:       case 'rank':
162:         [440, 554, 659, 880].forEach((f, i) => this.tone({ freq: f, dur: 0.32, type: 'triangle', gain: 0.08, delay: i * 0.09 }));
163:         break;
164:       case 'boon':
165:         [330, 440, 660].forEach((f, i) => this.tone({ freq: f, dur: 0.5, type: 'sine', gain: 0.08, delay: i * 0.08 }));
166:         break;
167:       case 'victory':
168:         [261, 329, 392, 523, 659].forEach((f, i) => this.tone({ freq: f, dur: 0.7, type: 'triangle', gain: 0.09, delay: i * 0.13 }));
169:         break;
170:       case 'error':
171:         this.tone({ freq: 140, to: 110, dur: 0.16, type: 'square', gain: 0.08 });
172:         break;
173:       default:
174:         break;
175:     }
176:   }
