178:   startMusic() {
179:     if (!this.ready || this.musicTimer) return;
180:     const chords = [
181:       [110, 164.81, 220, 293.66],
182:       [98, 146.83, 196, 261.63],
183:       [87.31, 130.81, 174.61, 246.94],
184:       [82.41, 123.47, 164.81, 220]
185:     ];
186:     const playChord = () => {
187:       if (!this.ready || this.settings.music === false) return;
188:       const t = this.ctx.currentTime;
189:       const chord = chords[this.musicStep % chords.length];
190:       const gain = this.musicGain;
191:       chord.forEach((freq, index) => {
192:         const osc = this.ctx.createOscillator();
193:         const g = this.ctx.createGain();
194:         const filter = this.ctx.createBiquadFilter();
195:         filter.type = 'lowpass';
196:         filter.frequency.value = 560 + index * 160;
197:         osc.type = index === 0 ? 'triangle' : 'sine';
198:         osc.frequency.value = freq;
199:         osc.detune.value = (Math.random() - 0.5) * 7;
200:         g.gain.setValueAtTime(0.0001, t);
201:         g.gain.exponentialRampToValueAtTime(0.045 / (index + 1), t + 1.6);
202:         g.gain.exponentialRampToValueAtTime(0.0001, t + 7.5);
203:         osc.connect(filter);
204:         filter.connect(g);
205:         g.connect(gain);
206:         osc.start(t);
207:         osc.stop(t + 7.7);
208:       });
209:       // A sparse, distant bell gives the tower a sense of scale.
210:       if (this.musicStep % 2 === 0) {
211:         const bell = this.ctx.createOscillator();
212:         const bg = this.ctx.createGain();
213:         bell.type = 'sine';
214:         bell.frequency.value = chord[2] * 4;
215:         bg.gain.setValueAtTime(0.0001, t + 1.1);
216:         bg.gain.exponentialRampToValueAtTime(0.016, t + 1.2);
217:         bg.gain.exponentialRampToValueAtTime(0.0001, t + 5.5);
218:         bell.connect(bg);
219:         bg.connect(gain);
220:         bell.start(t + 1.1);
221:         bell.stop(t + 5.6);
222:       }
223:       this.musicStep++;
224:     };
225:     playChord();
226:     this.musicTimer = setInterval(playChord, 7200);
227:   }
228: }

