/* Aetherborne: Warband — tactical descent UI */
:root {
  --bg: #08070c;
  --bg-2: #0d0b13;
  --panel: #121019;
  --panel-2: #191522;
  --panel-3: #211a2b;
  --ink: #f2eadb;
  --ink-soft: #d6c9bc;
  --muted: #a79cae;
  --muted-2: #776d80;
  --gold: #e7b96a;
  --gold-bright: #f7d99a;
  --gold-dim: rgba(231, 185, 106, 0.16);
  --rose: #f07d8b;
  --rose-dim: rgba(240, 125, 139, 0.14);
  --teal: #79e0c0;
  --teal-dim: rgba(121, 224, 192, 0.12);
  --violet: #a997ff;
  --line: rgba(231, 185, 106, 0.18);
  --line-soft: rgba(255, 255, 255, 0.075);
  --shadow: 0 26px 90px rgba(0, 0, 0, 0.58);
  --font-display: "Palatino Linotype", "Book Antiqua", Georgia, "Noto Serif KR", serif;
  --font-ui: "Trebuchet MS", "Apple SD Gothic Neo", "Malgun Gothic", "Noto Sans KR", sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-ui);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
button, input { font: inherit; color: inherit; }
button { border: 0; background: none; cursor: pointer; }
button:disabled { cursor: not-allowed; }
a { color: inherit; }
h1, h2, h3, h4, p { margin: 0; }
::selection { background: rgba(231, 185, 106, 0.28); color: #fff; }
.hidden { display: none !important; }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

/* ---------- ambient backdrop ---------- */
.ambient {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 74% 8%, rgba(231, 185, 106, 0.11), transparent 42%),
    radial-gradient(ellipse at 18% 82%, rgba(111, 86, 176, 0.12), transparent 52%),
    linear-gradient(180deg, #0a0810 0%, #08070c 58%, #06050a 100%);
}
.ambient-moon {
  position: absolute;
  top: -8vh;
  right: 12vw;
  width: 28vw;
  height: 28vw;
  min-width: 250px;
  min-height: 250px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 36%, rgba(255, 236, 199, 0.42), rgba(231, 185, 106, 0.1) 38%, transparent 68%);
  filter: blur(8px);
  opacity: 0.7;
}
.ambient-tower {
  position: absolute;
  left: 50%;
  bottom: -2vh;
  width: min(44vw, 560px);
  height: 88vh;
  transform: translateX(-50%);
  background: linear-gradient(180deg, rgba(40, 30, 52, 0.62), rgba(13, 11, 19, 0.92) 72%);
  clip-path: polygon(42% 0, 58% 0, 58% 7%, 66% 7%, 66% 16%, 74% 16%, 74% 31%, 82% 31%, 82% 48%, 92% 48%, 92% 100%, 8% 100%, 8% 48%, 18% 48%, 18% 31%, 26% 31%, 26% 16%, 34% 16%, 34% 7%, 42% 7%);
  opacity: 0.5;
  filter: drop-shadow(0 0 70px rgba(231, 185, 106, 0.06));
}
.ambient-tower::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 28px, rgba(255, 255, 255, 0.028) 28px 29px);
}
.ambient-ridge {
  position: absolute;
  left: -5%;
  right: -5%;
  bottom: -4vh;
  height: 30vh;
  background: linear-gradient(180deg, transparent, rgba(5, 4, 9, 0.92) 42%);
  clip-path: polygon(0 56%, 12% 44%, 20% 54%, 31% 30%, 44% 52%, 54% 38%, 67% 55%, 79% 33%, 91% 52%, 100% 42%, 100% 100%, 0 100%);
}
.ambient-embers { position: absolute; inset: 0; }
.ember {
  position: absolute;
  bottom: -10px;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--gold-bright);
  box-shadow: 0 0 8px rgba(247, 217, 154, 0.8);
  opacity: 0;
  animation: emberFloat linear infinite;
}
@keyframes emberFloat {
  0% { transform: translate3d(0, 0, 0) scale(0.6); opacity: 0; }
  12% { opacity: 0.55; }
  70% { opacity: 0.25; }
  100% { transform: translate3d(var(--drift, 30px), -86vh, 0) scale(1.15); opacity: 0; }
}
.ambient-grain {
  position: absolute;
  inset: 0;
  opacity: 0.28;
  background-image:
    repeating-radial-gradient(circle at 17% 32%, rgba(255, 255, 255, 0.035) 0 1px, transparent 1px 4px),
    repeating-radial-gradient(circle at 71% 64%, rgba(255, 255, 255, 0.025) 0 1px, transparent 1px 5px);
  mix-blend-mode: overlay;
}

/* ---------- screens ---------- */
.screen {
  position: fixed;
  inset: 0;
  z-index: 2;
  display: none;
  flex-direction: column;
  overflow: hidden;
}
.screen.is-active { display: flex; animation: screenIn 0.38s ease both; }
@keyframes screenIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ---------- typography / common ---------- */
.eyebrow {
  font-size: 0.66rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 700;
}
.brand-mark, .brand-small {
  font-size: 0.64rem;
  letter-spacing: 0.22em;
  color: var(--muted);
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 8px;
}
.brand-mark span { color: var(--gold); font-size: 1rem; }
.brand-small { color: var(--ink-soft); }
.brand-small span { color: var(--gold); margin-left: 4px; }

.icon-btn {
  width: 38px;
  height: 38px;
  border: 1px solid var(--line-soft);
  border-radius: 50%;
  display: inline-grid;
  place-items: center;
  color: var(--ink-soft);
  background: rgba(18, 16, 25, 0.6);
  transition: border-color 0.2s, color 0.2s, background 0.2s;
}
.icon-btn:hover { border-color: var(--gold); color: var(--gold-bright); background: rgba(231, 185, 106, 0.08); }
.icon-btn.small { width: 32px; height: 32px; font-size: 0.82rem; }

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 11px 20px;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: rgba(18, 16, 25, 0.72);
  color: var(--ink-soft);
  letter-spacing: 0.04em;
  font-size: 0.82rem;
  transition: transform 0.16s ease, border-color 0.2s, background 0.2s, color 0.2s;
}
.btn:hover:not(:disabled) { transform: translateY(-1px); border-color: rgba(231, 185, 106, 0.55); color: var(--gold-bright); }
.btn:active:not(:disabled) { transform: translateY(0); }
.btn:disabled { opacity: 0.32; }
.btn-primary {
  background: linear-gradient(135deg, #f1cc86, #c9964e);
  border-color: #f4d89e;
  color: #21160a;
  font-weight: 800;
  box-shadow: 0 10px 28px rgba(231, 185, 106, 0.16);
}
.btn-primary:hover:not(:disabled) { background: linear-gradient(135deg, #ffe2a4, #dba95d); color: #1a1005; }
.btn-secondary { border-color: rgba(231, 185, 106, 0.32); color: var(--gold-bright); }
.btn-ghost { border-color: transparent; color: var(--muted); background: transparent; }
.btn-ghost:hover:not(:disabled) { color: var(--gold-bright); background: rgba(231, 185, 106, 0.06); }
.btn-large { padding: 14px 26px; min-height: 50px; font-size: 0.92rem; }

/* ---------- title ---------- */
.screen-title { justify-content: space-between; }
.title-top {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 26px clamp(20px, 5vw, 72px);
}
.title-top-actions { display: flex; align-items: center; gap: 18px; }
.legacy-link {
  font-size: 0.58rem;
  letter-spacing: 0.18em;
  color: var(--muted-2);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
.legacy-link:hover { color: var(--gold); border-color: var(--gold); }
.title-main {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 1540px;
  margin: 0 auto;
  padding: 1vh clamp(20px, 6vw, 96px) 2vh;
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(300px, 0.75fr);
  align-items: center;
  gap: clamp(24px, 5vw, 80px);
  flex: 1;
  min-height: 0;
}
.title-copy { max-width: 780px; }
.game-title {
  margin: 12px 0 2px;
  font-family: var(--font-display);
  font-size: clamp(3.6rem, 8.6vw, 9.2rem);
  line-height: 0.84;
  letter-spacing: 0.035em;
  font-weight: 400;
  color: var(--ink);
  text-shadow: 0 0 60px rgba(231, 185, 106, 0.13);
}
.game-title span { color: var(--gold); }
.title-rule {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 16px 0 24px;
  max-width: 520px;
}
.title-rule span { height: 1px; flex: 1; background: linear-gradient(90deg, transparent, var(--line)); }
.title-rule span:last-child { background: linear-gradient(90deg, var(--line), transparent); }
.title-rule em {
  font-family: var(--font-display);
  font-style: normal;
  font-size: 0.84rem;
  letter-spacing: 0.38em;
  color: var(--gold);
}
.title-blurb {
  max-width: 650px;
  color: var(--muted);
  font-size: clamp(0.86rem, 1.05vw, 1rem);
  line-height: 1.9;
  word-break: keep-all;
}
.title-actions { display: flex; flex-wrap: wrap; gap: 12px; margin: 30px 0 24px; align-items: center; }
.title-features {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  padding-top: 20px;
  border-top: 1px solid var(--line-soft);
  max-width: 660px;
}
.title-features span { font-size: 0.68rem; letter-spacing: 0.08em; color: var(--muted-2); }
.title-features b { color: var(--gold-bright); font-size: 0.9rem; margin-right: 4px; }
.title-note { margin-top: 14px; font-size: 0.7rem; color: var(--muted-2); }

.title-preview { display: flex; flex-direction: column; gap: 22px; }
.preview-frame {
  position: relative;
  padding: 26px 26px 22px;
  border: 1px solid var(--line);
  background:
    linear-gradient(160deg, rgba(34, 28, 44, 0.74), rgba(13, 11, 19, 0.86)),
    repeating-linear-gradient(0deg, transparent 0 30px, rgba(255, 255, 255, 0.02) 30px 31px);
  box-shadow: var(--shadow);
  clip-path: polygon(0 12px, 12px 0, calc(100% - 12px) 0, 100% 12px, 100% calc(100% - 12px), calc(100% - 12px) 100%, 12px 100%, 0 calc(100% - 12px));
}
.preview-frame::before {
  content: "";
  position: absolute;
  inset: 8px;
  border: 1px solid rgba(231, 185, 106, 0.08);
  pointer-events: none;
}
.preview-kicker { font-size: 0.58rem; letter-spacing: 0.26em; color: var(--gold); }
.preview-sigils { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin: 22px 0 24px; }
.preview-sigil {
  aspect-ratio: 1;
  border: 1px solid var(--line-soft);
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 1.5rem;
  color: var(--gold-bright);
  background: radial-gradient(circle at 34% 28%, rgba(231, 185, 106, 0.14), rgba(18, 16, 25, 0.4) 62%);
  box-shadow: inset 0 0 24px rgba(0, 0, 0, 0.35);
  position: relative;
}
.preview-sigil::after {
  content: attr(data-label);
  position: absolute;
  bottom: -15px;
  font-size: 0.44rem;
  letter-spacing: 0.08em;
  color: var(--muted-2);
  white-space: nowrap;
}
.preview-caption { display: flex; flex-direction: column; gap: 5px; }
.preview-caption b { font-family: var(--font-display); font-size: 1.15rem; font-weight: 400; color: var(--ink); }
.preview-caption span { color: var(--muted); font-size: 0.72rem; line-height: 1.65; word-break: keep-all; }
.preview-stamp {
  margin-top: 22px;
  padding-top: 12px;
  border-top: 1px solid var(--line-soft);
  font-size: 0.54rem;
  letter-spacing: 0.34em;
  color: var(--muted-2);
  text-align: right;
}
.title-quote {
  padding-left: 16px;
  border-left: 1px solid var(--line);
  color: var(--muted);
  font-family: var(--font-display);
  font-size: 0.9rem;
  line-height: 1.7;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.title-quote span { font-family: var(--font-ui); font-size: 0.6rem; letter-spacing: 0.12em; color: var(--muted-2); }
.title-footer {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 18px clamp(20px, 5vw, 72px) calc(18px + env(safe-area-inset-bottom));
  border-top: 1px solid var(--line-soft);
  font-size: 0.56rem;
  letter-spacing: 0.14em;
  color: var(--muted-2);
}

/* __APPEND__ */

