.option-name { font-family: var(--font-display); font-size: 1.04rem; line-height: 1.2; color: var(--ink); }
.option-english { display: block; font-family: var(--font-ui); font-size: 0.54rem; letter-spacing: 0.15em; color: var(--muted-2); text-transform: uppercase; margin-top: 3px; }
