}

.detail-panel {
  min-height: 0;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 6px;
  background:
    linear-gradient(160deg, rgba(29, 24, 39, 0.82), rgba(11, 9, 17, 0.9)),
    repeating-linear-gradient(0deg, transparent 0 34px, rgba(255, 255, 255, 0.018) 34px 35px);
