}
.detail-panel::-webkit-scrollbar { width: 6px; }
.detail-panel::-webkit-scrollbar-thumb { background: var(--line); border-radius: 4px; }
.detail-head { display: flex; gap: 14px; align-items: flex-start; padding-bottom: 16px; border-bottom: 1px solid var(--line-soft); }
.detail-head .option-glyph { flex-basis: 52px; width: 52px; height: 52px; font-size: 1.5rem; }
.detail-head h3 { font-family: var(--font-display); font-size: 1.5rem; font-weight: 400; line-height: 1.1; }
.detail-head p { margin-top: 5px; color: var(--gold); font-size: 0.64rem; letter-spacing: 0.08em; }
.detail-section { padding-top: 15px; }
.detail-section + .detail-section { border-top: 1px solid var(--line-soft); }
.detail-label { display: flex; align-items: center; justify-content: space-between; font-size: 0.56rem; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted-2); margin-bottom: 8px; }
.detail-label b { color: var(--gold); font-weight: 600; letter-spacing: 0.06em; }
.detail-desc { color: var(--muted); font-size: 0.73rem; line-height: 1.7; word-break: keep-all; }
.detail-chip-row { display: flex; flex-wrap: wrap; gap: 5px; }
.detail-chip {
  padding: 3px 7px;
  border-radius: 2px;
