  background: rgba(255, 255, 255, 0.025);
  font-size: 0.58rem;
  color: var(--ink-soft);
}
.detail-chip.good { color: var(--teal); border-color: rgba(121, 224, 192, 0.25); background: var(--teal-dim); }
.detail-chip.bad { color: var(--rose); border-color: rgba(240, 125, 139, 0.25); background: var(--rose-dim); }
.detail-chip.gold { color: var(--gold); border-color: rgba(231, 185, 106, 0.28); background: var(--gold-dim); }
.detail-list { display: flex; flex-direction: column; gap: 7px; }
.detail-list li { list-style: none; display: flex; gap: 8px; color: var(--muted); font-size: 0.7rem; line-height: 1.55; word-break: keep-all; }
.detail-list li::before { content: "◆"; color: var(--gold); font-size: 0.5rem; line-height: 1.9; }
.detail-list.cons li::before { content: "◇"; color: var(--rose); }
.detail-list { margin: 0; padding: 0; }
.ability-box {
  border: 1px solid rgba(231, 185, 106, 0.22);
