}
.ability-box + .ability-box { margin-top: 7px; }
.ability-box h4 { font-size: 0.78rem; color: var(--gold-bright); display: flex; justify-content: space-between; gap: 8px; }
.ability-box h4 span { font-size: 0.56rem; color: var(--muted-2); font-weight: 400; }
.ability-box p { margin-top: 4px; color: var(--muted); font-size: 0.66rem; line-height: 1.6; word-break: keep-all; }

.stat-block { display: flex; flex-direction: column; gap: 7px; }
.stat-line { display: grid; grid-template-columns: 46px 1fr 30px; gap: 8px; align-items: center; }
.stat-line > span { font-size: 0.62rem; color: var(--muted); }
.stat-line > b { font-size: 0.68rem; color: var(--ink); text-align: right; font-weight: 600; }
.stat-track { height: 5px; background: rgba(255, 255, 255, 0.06); border-radius: 4px; overflow: hidden; }
