.derived-cell span { display: block; font-size: 0.53rem; letter-spacing: 0.1em; color: var(--muted-2); text-transform: uppercase; }
.derived-cell b { display: block; margin-top: 2px; font-size: 0.9rem; color: var(--ink); }
.synergy-note {
  margin-top: 9px;
  padding: 8px 10px;
  border-left: 2px solid var(--gold);
  background: rgba(231, 185, 106, 0.055);
