  line-height: 1.6;
  word-break: keep-all;
}
.create-extra { margin-top: 14px; }
.name-form {
  max-width: 640px;
  padding: 26px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: linear-gradient(150deg, rgba(30, 24, 40, 0.75), rgba(12, 10, 18, 0.8));
}
.name-form label { display: block; font-size: 0.62rem; letter-spacing: 0.16em; color: var(--gold); margin-bottom: 8px; text-transform: uppercase; }
.name-input {
  width: 100%;
  padding: 14px 16px;
  background: rgba(7, 6, 11, 0.68);
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.35rem;
  letter-spacing: 0.03em;
  outline: none;
}
.name-input:focus { border-color: var(--gold); box-shadow: 0 0 0 3px rgba(231, 185, 106, 0.1); }
.name-form p { margin-top: 10px; color: var(--muted-2); font-size: 0.68rem; line-height: 1.6; }
.name-form .btn { margin-top: 16px; }

.create-footer {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 16px;
  padding: 16px clamp(18px, 4vw, 54px) calc(16px + env(safe-area-inset-bottom));
  border-top: 1px solid var(--line-soft);
  background: rgba(9, 8, 14, 0.62);
  backdrop-filter: blur(14px);
}
.create-footer #btn-create-next { justify-self: end; min-width: 150px; }
.create-hint { font-size: 0.62rem; color: var(--muted-2); text-align: center; line-height: 1.5; }

/* ---------- party ---------- */
.screen-party { background: linear-gradient(180deg, rgba(8, 7, 12, 0.36), rgba(8, 7, 12, 0.8)); }
.party-count {
  justify-self: end;
  font-family: var(--font-display);
  font-size: 1.15rem;
  color: var(--gold-bright);
  letter-spacing: 0.08em;
}
.party-layout {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(310px, 390px);
  gap: clamp(16px, 2.4vw, 32px);
  padding: clamp(16px, 2.4vw, 30px) clamp(18px, 4vw, 54px);
}
.formation-panel { min-height: 0; display: flex; flex-direction: column; }
.panel-heading h2 { margin: 6px 0 7px; font-family: var(--font-display); font-size: clamp(1.5rem, 2.5vw, 2.2rem); font-weight: 400; }
.panel-heading p:last-child { color: var(--muted); font-size: 0.74rem; line-height: 1.65; max-width: 650px; word-break: keep-all; }
.panel-heading.compact h2 { font-size: 1.35rem; margin-bottom: 0; }
.formation-board {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  margin: 20px 0 14px;
}
.formation-row { display: grid; grid-template-columns: 60px 1fr 1fr; gap: 9px; align-items: stretch; }
.formation-row-label {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2px;
  padding-left: 2px;
}
.formation-row-label b { font-size: 0.64rem; color: var(--ink-soft); letter-spacing: 0.08em; }
.formation-row-label span { font-size: 0.48rem; letter-spacing: 0.14em; color: var(--muted-2); }
.slot {
  position: relative;
  min-height: 122px;
  border: 1px solid var(--line-soft);
  border-radius: 5px;
  background: linear-gradient(150deg, rgba(27, 22, 36, 0.6), rgba(10, 8, 15, 0.65));
  padding: 10px;
  text-align: left;
  transition: border-color 0.18s, background 0.18s, transform 0.18s;
  overflow: hidden;
}
.slot::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 0%, rgba(231, 185, 106, 0.06), transparent 60%);
  pointer-events: none;
}
.slot:hover { border-color: rgba(231, 185, 106, 0.4); }
.slot.is-selected { border-color: var(--gold); box-shadow: inset 0 0 0 1px rgba(231, 185, 106, 0.4); }
.slot.is-target-swap { border-color: var(--teal); box-shadow: 0 0 0 2px rgba(121, 224, 192, 0.14); }
.slot.is-empty {
  border-style: dashed;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  color: var(--muted-2);
}
.slot.is-empty:hover { color: var(--gold); background: rgba(231, 185, 106, 0.035); }
.slot-plus { font-size: 1.4rem; line-height: 1; color: var(--line); }
.slot-empty-label { font-size: 0.6rem; letter-spacing: 0.12em; }
.slot-row-badge {
  position: absolute;
  top: 8px;
  right: 8px;
  font-size: 0.46rem;
  letter-spacing: 0.1em;
  color: var(--muted-2);
  border: 1px solid var(--line-soft);
  padding: 1px 4px;
  border-radius: 2px;
}
.slot-char { position: relative; display: flex; gap: 9px; align-items: flex-start; }
.slot-avatar {
  flex: 0 0 38px;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 1.05rem;
  color: var(--card-color, var(--gold));
  border: 1px solid color-mix(in srgb, var(--card-color, var(--gold)) 45%, transparent);
  background: radial-gradient(circle at 32% 26%, color-mix(in srgb, var(--card-color, var(--gold)) 18%, transparent), rgba(8, 7, 12, 0.55));
}
.slot-char h4 { font-family: var(--font-display); font-size: 0.96rem; font-weight: 400; line-height: 1.15; }
.slot-char p { margin-top: 2px; font-size: 0.56rem; color: var(--muted); }
.slot-char .slot-kit { color: var(--gold); font-size: 0.52rem; margin-top: 2px; }
.slot-stats { margin-top: 9px; display: grid; gap: 4px; }
.mini-bar { height: 5px; background: rgba(255, 255, 255, 0.06); border-radius: 3px; overflow: hidden; }
.mini-bar i { display: block; height: 100%; border-radius: 3px; background: linear-gradient(90deg, #f07d8b, #f2c47d); transition: width 0.25s; }
.mini-bar.aether i { background: linear-gradient(90deg, #6f9dff, #a997ff); }
.slot-hp-text { font-size: 0.5rem; color: var(--muted-2); display: flex; justify-content: space-between; }
.formation-legend { display: flex; flex-wrap: wrap; gap: 8px 20px; padding-top: 12px; border-top: 1px solid var(--line-soft); }
.formation-legend span { font-size: 0.58rem; color: var(--muted-2); display: flex; align-items: center; gap: 6px; }
.dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; }
.dot-front { background: var(--rose); }
.dot-mid { background: var(--gold); }
.dot-back { background: var(--teal); }

.party-side { min-height: 0; display: flex; flex-direction: column; gap: 12px; }
.party-roster { display: flex; flex-direction: column; gap: 6px; overflow-y: auto; padding-right: 4px; scrollbar-width: thin; scrollbar-color: var(--line) transparent; }
.roster-card {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 9px;
  border: 1px solid var(--line-soft);
  border-radius: 4px;
  background: rgba(20, 16, 28, 0.6);
  text-align: left;
  transition: border-color 0.18s, background 0.18s;
}
.roster-card:hover, .roster-card.is-selected { border-color: rgba(231, 185, 106, 0.5); background: rgba(231, 185, 106, 0.06); }
.roster-card .slot-avatar { flex-basis: 32px; width: 32px; height: 32px; font-size: 0.9rem; }
.roster-card h4 { font-size: 0.78rem; font-weight: 600; }
.roster-card p { font-size: 0.56rem; color: var(--muted); margin-top: 2px; }
.roster-card .roster-slot { margin-left: auto; font-size: 0.5rem; color: var(--muted-2); border: 1px solid var(--line-soft); padding: 1px 4px; border-radius: 2px; }
.party-detail {
  flex: 1;
  min-height: 130px;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 5px;
  padding: 13px;
  background: linear-gradient(160deg, rgba(30, 24, 40, 0.7), rgba(11, 9, 17, 0.78));
  scrollbar-width: thin;
}
.party-detail .detail-head { padding-bottom: 10px; }
.party-detail .detail-head h3 { font-size: 1.15rem; }
.party-detail .detail-section { padding-top: 10px; }
.party-detail .detail-desc { font-size: 0.66rem; }
.party-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 15px clamp(18px, 4vw, 54px) calc(15px + env(safe-area-inset-bottom));
  border-top: 1px solid var(--line-soft);
  background: rgba(9, 8, 14, 0.62);
  backdrop-filter: blur(14px);
}
.party-footer-actions { display: flex; flex-wrap: wrap; gap: 8px; justify-content: flex-end; }

/* __APPEND__ */

