.resource { font-size: 0.58rem; color: var(--muted-2); display: flex; align-items: center; gap: 4px; white-space: nowrap; }
.resource b { color: var(--gold-bright); font-size: 0.82rem; }
.dungeon-stage { position: relative; flex: 1; min-height: 0; overflow: hidden; }
#dungeon-canvas { display: block; width: 100%; height: 100%; }
.dungeon-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 40%, rgba(4, 3, 7, 0.72) 100%);
  mix-blend-mode: multiply;
}
.dungeon-toast {
  position: absolute;
  top: 18px;
  left: 50%;
  transform: translateX(-50%);
  max-width: min(90vw, 520px);
  padding: 9px 18px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: rgba(13, 10, 19, 0.92);
  color: var(--ink-soft);
  font-size: 0.7rem;
  letter-spacing: 0.02em;
  box-shadow: var(--shadow);
  z-index: 4;
  text-align: center;
  animation: toastIn 0.24s ease both;
}
.dungeon-toast b { color: var(--gold-bright); }
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, -6px); } to { opacity: 1; transform: translate(-50%, 0); } }
.dungeon-legend {
  position: absolute;
  left: 16px;
  bottom: 16px;
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  padding: 8px 10px;
  border: 1px solid var(--line-soft);
  border-radius: 3px;
  background: rgba(8, 7, 12, 0.7);
  backdrop-filter: blur(8px);
  z-index: 3;
}
.dungeon-legend span { display: flex; align-items: center; gap: 5px; font-size: 0.5rem; color: var(--muted-2); letter-spacing: 0.04em; }
.legend-dot { width: 6px; height: 6px; border-radius: 50%; display: inline-block; box-shadow: 0 0 8px currentColor; }
.legend-encounter { background: var(--rose); color: var(--rose); }
.legend-chest { background: var(--gold); color: var(--gold); }
.legend-shrine { background: var(--teal); color: var(--teal); }
.legend-stairs { background: var(--violet); color: var(--violet); }
.minimap-wrap {
  position: absolute;
  top: 14px;
  right: 14px;
  padding: 6px;
  border: 1px solid var(--line-soft);
  border-radius: 3px;
  background: rgba(8, 7, 12, 0.72);
  backdrop-filter: blur(8px);
  z-index: 3;
}
#minimap { display: block; width: 150px; height: 104px; opacity: 0.9; }
.minimap-wrap span { display: block; text-align: center; font-size: 0.45rem; letter-spacing: 0.18em; color: var(--muted-2); margin-top: 3px; }
.dungeon-controls {
  position: absolute;
  right: 18px;
  bottom: 16px;
  display: flex;
  align-items: flex-end;
  gap: 14px;
  z-index: 4;
}
.dpad { display: grid; grid-template-columns: repeat(3, 38px); grid-template-rows: repeat(3, 38px); gap: 3px; }
.dpad-btn {
  border: 1px solid var(--line-soft);
  border-radius: 4px;
  background: rgba(15, 12, 22, 0.8);
  color: var(--muted);
  display: grid;
  place-items: center;
  font-size: 0.7rem;
  touch-action: none;
  transition: border-color 0.15s, background 0.15s, color 0.15s;
}
.dpad-btn:hover, .dpad-btn.is-held { border-color: var(--gold); color: var(--gold-bright); background: rgba(231, 185, 106, 0.1); }
.dpad-btn.up { grid-column: 2; grid-row: 1; }
.dpad-btn.left { grid-column: 1; grid-row: 2; }
.dpad-btn.down { grid-column: 2; grid-row: 3; }
.dpad-btn.right { grid-column: 3; grid-row: 2; }
.interact-btn {
  width: 62px;
  height: 62px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: radial-gradient(circle at 35% 28%, rgba(231, 185, 106, 0.18), rgba(13, 10, 19, 0.9));
  color: var(--gold-bright);
  font-family: var(--font-display);
  font-size: 1.2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  box-shadow: 0 0 0 5px rgba(231, 185, 106, 0.035);
  touch-action: none;
}
.interact-btn small { font-family: var(--font-ui); font-size: 0.42rem; letter-spacing: 0.06em; color: var(--muted); }
.interact-btn:hover { border-color: var(--gold); background: rgba(231, 185, 106, 0.13); }
.party-bar {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 6px;
  padding: 8px clamp(12px, 3vw, 42px) calc(8px + env(safe-area-inset-bottom));
  border-top: 1px solid var(--line-soft);
  background: rgba(9, 8, 14, 0.72);
  backdrop-filter: blur(12px);
  z-index: 3;
}
.party-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 7px;
  border: 1px solid var(--line-soft);
  border-radius: 3px;
  background: rgba(20, 16, 28, 0.55);
  min-width: 0;
}
.party-chip .slot-avatar { flex: 0 0 27px; width: 27px; height: 27px; font-size: 0.75rem; }
.party-chip-info { min-width: 0; flex: 1; }
.party-chip-info h4 { font-size: 0.62rem; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.party-chip-info p { font-size: 0.46rem; color: var(--muted-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.party-chip .mini-bar { margin-top: 3px; height: 4px; }
.party-chip.is-down { opacity: 0.4; filter: grayscale(0.7); }

/* ---------- battle ---------- */
.screen-battle { background: radial-gradient(ellipse at 50% 36%, rgba(68, 44, 65, 0.3), transparent 58%), #08070c; }
.battle-shell { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.battle-top {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 16px;
  padding: 10px clamp(12px, 3vw, 38px);
  border-bottom: 1px solid var(--line-soft);
  background: rgba(9, 8, 14, 0.7);
  backdrop-filter: blur(12px);
  z-index: 4;
}
.battle-round-box { display: flex; align-items: baseline; gap: 7px; }
.battle-round-box span { font-size: 0.48rem; letter-spacing: 0.18em; color: var(--muted-2); }
.battle-round-box b { font-family: var(--font-display); font-size: 1.35rem; color: var(--gold-bright); font-weight: 400; }
.turn-order-wrap { display: flex; align-items: center; gap: 10px; min-width: 0; }
.turn-label { font-size: 0.44rem; letter-spacing: 0.16em; color: var(--muted-2); white-space: nowrap; }
.turn-order { display: flex; align-items: center; gap: 3px; overflow: hidden; min-width: 0; }
.turn-token {
  flex: 0 0 23px;
  width: 23px;
  height: 23px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.62rem;
  border: 1px solid var(--line-soft);
  background: rgba(20, 16, 28, 0.7);
  color: var(--muted);
  transition: all 0.2s;
}
.turn-token.is-ally { border-color: rgba(121, 224, 192, 0.25); color: var(--teal); }
.turn-token.is-enemy { border-color: rgba(240, 125, 139, 0.25); color: var(--rose); }
.turn-token.is-current { transform: scale(1.18); background: var(--gold); color: #1c1308; border-color: var(--gold); box-shadow: 0 0 12px rgba(231, 185, 106, 0.4); }
.turn-token.is-dead { opacity: 0.22; text-decoration: line-through; }
.battle-top-actions { display: flex; gap: 5px; }
.battlefield {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(140px, 0.26fr) minmax(0, 1fr);
  gap: clamp(6px, 1.4vw, 20px);
  padding: clamp(8px, 1.6vw, 22px) clamp(10px, 2.4vw, 34px);
  overflow: hidden;
}
.battle-side { min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 7px; }
.side-label { display: flex; justify-content: space-between; align-items: center; padding: 0 3px; }
.side-label span { font-size: 0.46rem; letter-spacing: 0.18em; color: var(--muted-2); }
.side-label b { font-size: 0.6rem; color: var(--ink-soft); font-weight: 500; }
.enemies-side .side-label { flex-direction: row-reverse; }
.unit-grid {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-template-rows: repeat(3, minmax(0, 1fr));
  gap: clamp(4px, 0.7vw, 9px);
}
.unit {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 7px 8px;
  border: 1px solid var(--line-soft);
  border-radius: 5px;
  background: linear-gradient(150deg, rgba(29, 24, 39, 0.75), rgba(11, 9, 17, 0.82));
  transition: border-color 0.18s, transform 0.18s, box-shadow 0.18s, opacity 0.3s;
  overflow: hidden;
}
.unit::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(circle at 10% 0%, var(--unit-glow, rgba(231, 185, 106, 0.1)), transparent 55%);
}
.unit.is-ally { border-left: 2px solid rgba(121, 224, 192, 0.55); }
.unit.is-enemy { border-right: 2px solid rgba(240, 125, 139, 0.55); }
.unit.is-active { border-color: var(--gold); box-shadow: 0 0 0 1px rgba(231, 185, 106, 0.4), 0 0 24px rgba(231, 185, 106, 0.12); }
.unit.is-targetable { cursor: crosshair; border-color: var(--rose); box-shadow: 0 0 0 1px rgba(240, 125, 139, 0.5), 0 0 22px rgba(240, 125, 139, 0.18); animation: targetPulse 1.2s ease-in-out infinite; }
.unit.is-targetable.is-ally { border-color: var(--teal); box-shadow: 0 0 0 1px rgba(121, 224, 192, 0.5), 0 0 22px rgba(121, 224, 192, 0.18); }
.unit.is-dead { opacity: 0.26; filter: grayscale(0.85); }
.unit.is-dead .unit-avatar { transform: rotate(-12deg); }
.unit.is-attacking { animation: lungeAlly 0.36s ease; }
.enemies-side .unit.is-attacking { animation: lungeEnemy 0.36s ease; }
.unit.is-hit { animation: hitShake 0.28s ease; }
.unit.is-healed { animation: healGlow 0.5s ease; }
@keyframes targetPulse { 0%, 100% { box-shadow: 0 0 0 1px rgba(240, 125, 139, 0.5), 0 0 14px rgba(240, 125, 139, 0.1); } 50% { box-shadow: 0 0 0 2px rgba(240, 125, 139, 0.7), 0 0 26px rgba(240, 125, 139, 0.25); } }
@keyframes lungeAlly { 0%, 100% { transform: translateX(0); } 45% { transform: translateX(14px); } }
@keyframes lungeEnemy { 0%, 100% { transform: translateX(0); } 45% { transform: translateX(-14px); } }
@keyframes hitShake { 0%, 100% { transform: translateX(0); } 20% { transform: translateX(-5px); } 40% { transform: translateX(4px); } 60% { transform: translateX(-3px); } 80% { transform: translateX(2px); } }
@keyframes healGlow { 0% { box-shadow: inset 0 0 0 0 rgba(121, 224, 192, 0); } 35% { box-shadow: inset 0 0 24px 2px rgba(121, 224, 192, 0.25); } 100% { box-shadow: inset 0 0 0 0 rgba(121, 224, 192, 0); } }
.unit-avatar {
  position: relative;
  z-index: 1;
  flex: 0 0 38px;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 1.05rem;
  color: var(--unit-color, var(--gold));
  border: 1px solid color-mix(in srgb, var(--unit-color, var(--gold)) 45%, transparent);
  background: radial-gradient(circle at 32% 26%, color-mix(in srgb, var(--unit-color, var(--gold)) 22%, transparent), rgba(8, 7, 12, 0.58));
  box-shadow: inset 0 0 18px rgba(0, 0, 0, 0.34);
  transition: transform 0.2s;
}
.unit-avatar .unit-row {
  position: absolute;
  bottom: -3px;
  right: -3px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.4rem;
  font-weight: 800;
  color: #0c0a10;
  background: var(--gold);
  border: 1px solid rgba(0, 0, 0, 0.4);
}
.unit-avatar .unit-row.front { background: var(--rose); }
.unit-avatar .unit-row.mid { background: var(--gold); }
.unit-avatar .unit-row.back { background: var(--teal); }
.unit-body { position: relative; z-index: 1; min-width: 0; flex: 1; }
.unit-name { display: flex; align-items: center; gap: 4px; font-size: 0.66rem; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.unit-name .boss-mark { color: var(--gold); font-size: 0.55rem; }
.unit-meta { margin-top: 1px; font-size: 0.47rem; color: var(--muted-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.unit-bars { margin-top: 4px; display: grid; gap: 2px; }
.unit-bar { height: 4px; border-radius: 3px; background: rgba(255, 255, 255, 0.07); overflow: hidden; }
.unit-bar i { display: block; height: 100%; border-radius: 3px; background: linear-gradient(90deg, #d4576a, #f2a06a); transition: width 0.3s; }
.unit-bar.aether i { background: linear-gradient(90deg, #577dd4, #a997ff); }
.unit-bar.shield i { background: linear-gradient(90deg, #79e0c0, #b7f2df); }
.unit-statuses { display: flex; flex-wrap: wrap; gap: 2px; margin-top: 3px; min-height: 12px; }
.status-chip {
  font-size: 0.42rem;
  line-height: 1;
  padding: 2px 3px;
  border-radius: 2px;
  border: 1px solid var(--line-soft);
  color: var(--muted);
  background: rgba(255, 255, 255, 0.03);
  white-space: nowrap;
}
.status-chip.buff { color: var(--teal); border-color: rgba(121, 224, 192, 0.2); }
.status-chip.debuff { color: var(--rose); border-color: rgba(240, 125, 139, 0.2); }
.status-chip.control { color: var(--violet); border-color: rgba(169, 151, 255, 0.24); }
.float-text {
  position: absolute;
  left: 50%;
  top: 4px;
  transform: translateX(-50%);
  z-index: 5;
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-weight: 700;
  color: #ffb0b0;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.8);
  pointer-events: none;
  animation: floatUp 0.85s ease-out both;
  white-space: nowrap;
}
.float-text.heal { color: var(--teal); }
.float-text.crit { color: var(--gold-bright); font-size: 1.3rem; }
.float-text.status { color: var(--violet); font-size: 0.66rem; font-family: var(--font-ui); }
@keyframes floatUp { 0% { opacity: 0; transform: translate(-50%, 4px) scale(0.9); } 15% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%, -30px) scale(1.05); } }

.battle-center { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; min-width: 0; }
.battle-round-banner {
  font-family: var(--font-display);
  font-size: 0.62rem;
  letter-spacing: 0.28em;
  color: var(--gold);
  opacity: 0.7;
  text-align: center;
}
.battle-message {
  min-height: 44px;
  padding: 7px 10px;
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  color: var(--muted);
  font-size: 0.62rem;
  line-height: 1.5;
  text-align: center;
  word-break: keep-all;
}
.battle-message b { color: var(--gold-bright); }
.battle-fx { position: absolute; inset: 0; pointer-events: none; }

.battle-bottom {
  display: grid;
  grid-template-columns: minmax(170px, 0.8fr) minmax(0, 1.5fr) minmax(180px, 0.9fr);
  gap: 10px;
  padding: 10px clamp(12px, 3vw, 38px) calc(10px + env(safe-area-inset-bottom));
  border-top: 1px solid var(--line-soft);
  background: rgba(9, 8, 14, 0.72);
  backdrop-filter: blur(12px);
  z-index: 4;
  max-height: 36vh;
}
.active-card { min-width: 0; border: 1px solid var(--line); border-radius: 5px; padding: 9px 11px; background: linear-gradient(150deg, rgba(31, 25, 42, 0.8), rgba(11, 9, 17, 0.85)); }
.active-card .active-kicker { font-size: 0.45rem; letter-spacing: 0.18em; color: var(--gold); }
.active-card h3 { margin-top: 3px; font-family: var(--font-display); font-size: 1.08rem; font-weight: 400; }
.active-card p { margin-top: 3px; color: var(--muted); font-size: 0.58rem; line-height: 1.45; }
.active-card .active-stats { display: flex; gap: 8px; margin-top: 7px; flex-wrap: wrap; }
.active-card .active-stats span { font-size: 0.5rem; color: var(--muted-2); }
.active-card .active-stats b { color: var(--ink-soft); }
.action-panel { min-width: 0; display: flex; flex-direction: column; gap: 6px; justify-content: center; }
.action-title { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.action-title b { font-size: 0.6rem; letter-spacing: 0.12em; color: var(--gold); }
.action-title span { font-size: 0.52rem; color: var(--muted-2); }
.action-buttons { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 5px; }
.action-btn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 7px 8px;
  min-height: 52px;
  border: 1px solid var(--line-soft);
  border-radius: 4px;
  background: rgba(20, 16, 28, 0.62);
  text-align: left;
  transition: border-color 0.16s, background 0.16s, transform 0.16s;
  overflow: hidden;
}
.action-btn:hover:not(:disabled) { border-color: var(--gold); background: rgba(231, 185, 106, 0.08); transform: translateY(-1px); }
.action-btn:disabled { opacity: 0.34; }
.action-btn .action-icon { font-size: 0.85rem; color: var(--gold-bright); line-height: 1; }
.action-btn .action-name { font-size: 0.58rem; color: var(--ink-soft); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.action-btn .action-cost { font-size: 0.44rem; color: var(--muted-2); }
.action-btn.is-selected { border-color: var(--gold); background: rgba(231, 185, 106, 0.12); box-shadow: inset 0 0 0 1px rgba(231, 185, 106, 0.3); }
.action-btn .key-hint { position: absolute; top: 3px; right: 4px; font-size: 0.4rem; color: var(--muted-2); }
.action-note { font-size: 0.52rem; color: var(--muted-2); line-height: 1.4; min-height: 14px; }
.action-note b { color: var(--teal); }
.battle-log {
  min-width: 0;
  max-height: 100%;
  overflow-y: auto;
  border: 1px solid var(--line-soft);
  border-radius: 4px;
  padding: 7px 9px;
  background: rgba(8, 7, 12, 0.45);
  font-size: 0.52rem;
  line-height: 1.55;
  color: var(--muted-2);
  scrollbar-width: thin;
}
.battle-log p { margin: 0 0 3px; }
.battle-log p:last-child { color: var(--ink-soft); }
.battle-log b { color: var(--gold); }
.battle-log .ally { color: var(--teal); }
.battle-log .enemy { color: var(--rose); }

/* ---------- overlay ---------- */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(4, 3, 8, 0.74);
  backdrop-filter: blur(9px);
  animation: overlayIn 0.2s ease both;
}
@keyframes overlayIn { from { opacity: 0; } to { opacity: 1; } }
.overlay-card {
  width: min(760px, 96vw);
  max-height: 88vh;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 6px;
  background:
    linear-gradient(160deg, rgba(31, 25, 42, 0.97), rgba(10, 8, 15, 0.98)),
    repeating-linear-gradient(0deg, transparent 0 36px, rgba(255, 255, 255, 0.015) 36px 37px);
  box-shadow: var(--shadow);
  padding: clamp(20px, 3.4vw, 34px);
  animation: cardIn 0.28s cubic-bezier(0.2, 0.7, 0.3, 1) both;
  scrollbar-width: thin;
  scrollbar-color: var(--line) transparent;
}
.overlay-card.wide { width: min(980px, 96vw); }
@keyframes cardIn { from { opacity: 0; transform: translateY(12px) scale(0.985); } to { opacity: 1; transform: translateY(0) scale(1); } }
.overlay-card h2 { margin: 6px 0 6px; font-family: var(--font-display); font-size: clamp(1.6rem, 3vw, 2.4rem); font-weight: 400; }
.overlay-card h3 { font-family: var(--font-display); font-size: 1.15rem; font-weight: 400; color: var(--gold-bright); }
.overlay-card > p { color: var(--muted); font-size: 0.76rem; line-height: 1.7; word-break: keep-all; }
.overlay-actions { display: flex; flex-wrap: wrap; gap: 8px; justify-content: flex-end; margin-top: 22px; padding-top: 16px; border-top: 1px solid var(--line-soft); }
.overlay-close { float: right; }
.manual-tabs { display: flex; gap: 5px; flex-wrap: wrap; margin: 18px 0 14px; }
.manual-tab { padding: 5px 10px; border: 1px solid var(--line-soft); border-radius: 2px; font-size: 0.6rem; color: var(--muted); }
.manual-tab.is-active { border-color: var(--gold); color: var(--gold-bright); background: var(--gold-dim); }
.manual-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 7px; }
.manual-entry { border: 1px solid var(--line-soft); border-radius: 4px; padding: 9px 10px; background: rgba(255, 255, 255, 0.018); }
.manual-entry h4 { font-size: 0.76rem; color: var(--ink); display: flex; gap: 6px; align-items: center; }
.manual-entry h4 span { color: var(--gold); }
.manual-entry p { margin-top: 4px; font-size: 0.62rem; color: var(--muted); line-height: 1.55; word-break: keep-all; }
.manual-entry .manual-meta { margin-top: 5px; font-size: 0.52rem; color: var(--muted-2); }
.reward-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 8px; margin: 16px 0; }
.reward-cell { border: 1px solid var(--line-soft); padding: 9px; border-radius: 4px; text-align: center; background: rgba(255, 255, 255, 0.02); }
.reward-cell span { display: block; font-size: 0.5rem; letter-spacing: 0.12em; color: var(--muted-2); text-transform: uppercase; }
.reward-cell b { display: block; margin-top: 3px; font-family: var(--font-display); font-size: 1.3rem; color: var(--gold-bright); font-weight: 400; }
.result-banner { text-align: center; padding: 6px 0 14px; }
.result-banner .result-glyph { font-size: 2.6rem; color: var(--gold); text-shadow: 0 0 30px rgba(231, 185, 106, 0.35); }
.result-banner h2 { margin-top: 8px; }
.level-up-list { display: flex; flex-direction: column; gap: 5px; margin-top: 10px; }
.level-up-row { display: flex; justify-content: space-between; gap: 10px; font-size: 0.66rem; color: var(--muted); padding: 6px 8px; border: 1px solid var(--line-soft); border-radius: 3px; }
.level-up-row b { color: var(--teal); }
.floor-card { text-align: center; }
.floor-card .floor-number { font-family: var(--font-display); font-size: 3.6rem; color: var(--gold-bright); line-height: 1; }
.floor-card .floor-name { font-family: var(--font-display); font-size: 1.8rem; margin-top: 6px; }
.floor-card .floor-desc { max-width: 540px; margin: 10px auto 0; color: var(--muted); font-size: 0.76rem; line-height: 1.7; word-break: keep-all; }

/* ---------- toasts / boot ---------- */
.toasts { position: fixed; right: 18px; bottom: 18px; z-index: 90; display: flex; flex-direction: column; gap: 6px; pointer-events: none; }
.toast {
  min-width: 180px;
  max-width: min(88vw, 360px);
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-left: 2px solid var(--gold);
  border-radius: 3px;
  background: rgba(13, 10, 19, 0.95);
  color: var(--ink-soft);
  font-size: 0.66rem;
  line-height: 1.5;
  box-shadow: var(--shadow);
  animation: toastSlide 0.24s ease both;
}
.toast b { color: var(--gold-bright); }
@keyframes toastSlide { from { opacity: 0; transform: translateX(12px); } to { opacity: 1; transform: translateX(0); } }
.boot {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  background: #08070c;
  transition: opacity 0.45s ease, visibility 0.45s;
}
.boot.is-gone { opacity: 0; visibility: hidden; }
.boot-mark { font-size: 2.4rem; color: var(--gold); animation: bootPulse 1.6s ease-in-out infinite; }
.boot p { font-size: 0.58rem; letter-spacing: 0.26em; color: var(--muted-2); text-transform: uppercase; }
@keyframes bootPulse { 0%, 100% { opacity: 0.5; transform: scale(0.96); } 50% { opacity: 1; transform: scale(1.04); } }

/* ---------- responsive ---------- */
@media (max-width: 1080px) {
  .title-main { grid-template-columns: 1fr; gap: 28px; padding-top: 0; }
  .title-preview { display: none; }
  .title-copy { max-width: 900px; }
  .create-layout { grid-template-columns: minmax(0, 1fr) minmax(290px, 350px); }
  .battlefield { grid-template-columns: minmax(0, 1fr) 90px minmax(0, 1fr); }
  .battle-bottom { grid-template-columns: minmax(150px, 0.7fr) minmax(0, 1.6fr); }
  .battle-log { display: none; }
  .battle-bottom.show-log { grid-template-columns: minmax(150px, 0.7fr) minmax(0, 1.6fr) minmax(180px, 0.9fr); }
  .battle-bottom.show-log .battle-log { display: block; }
}
@media (max-width: 820px) {
  .screen { overflow-y: auto; }
  .title-top { padding: 16px 18px; }
  .title-main { padding: 0 20px 18px; }
  .game-title { font-size: clamp(3.2rem, 15vw, 6rem); }
  .title-blurb { font-size: 0.82rem; line-height: 1.75; }
  .title-actions { margin: 22px 0 18px; }
  .title-features { gap: 6px 16px; }
  .title-footer { flex-wrap: wrap; gap: 6px 14px; padding: 12px 18px calc(12px + env(safe-area-inset-bottom)); }
  .title-footer span:first-child { flex-basis: 100%; }

  .create-header, .party-header { grid-template-columns: 1fr auto; padding: 12px 16px; }
  .step-track { display: none; }
  .create-layout { grid-template-columns: 1fr; padding: 14px 16px; overflow-y: auto; }
  .create-main { overflow: visible; padding-right: 0; }
  .detail-panel { max-height: none; align-self: stretch; order: 2; }
  .create-grid { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 8px; }
  .option-card { min-height: 134px; padding: 11px; }
  .option-desc { -webkit-line-clamp: 2; font-size: 0.64rem; }
  .create-footer { grid-template-columns: auto 1fr auto; padding: 12px 16px calc(12px + env(safe-area-inset-bottom)); }
  .create-hint { font-size: 0.56rem; }

  .party-layout { grid-template-columns: 1fr; padding: 14px 16px; overflow-y: auto; }
  .party-side { min-height: 320px; }
  .formation-row { grid-template-columns: 44px 1fr 1fr; }
  .slot { min-height: 110px; }
  .party-footer { flex-wrap: wrap; padding: 12px 16px calc(12px + env(safe-area-inset-bottom)); }
  .party-footer-actions { flex: 1; justify-content: flex-end; }
  .party-footer-actions .btn { padding: 9px 12px; font-size: 0.72rem; }

  .dungeon-top { grid-template-columns: 1fr auto; padding: 9px 14px; gap: 8px; }
  .dungeon-floor p:last-child { display: none; }
  .dungeon-objective { display: none; }
  .dungeon-resources { gap: 6px; }
  .resource { font-size: 0.5rem; }
  .resource b { font-size: 0.72rem; }
  .dungeon-legend { left: 10px; bottom: 10px; max-width: 48vw; }
  .dungeon-controls { right: 10px; bottom: 10px; gap: 8px; }
  .dpad { grid-template-columns: repeat(3, 40px); grid-template-rows: repeat(3, 40px); }
  .interact-btn { width: 56px; height: 56px; font-size: 1.05rem; }
  .minimap-wrap { top: 10px; right: 10px; }
  #minimap { width: 112px; height: 78px; }
  .party-bar { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 4px; padding: 6px 10px calc(6px + env(safe-area-inset-bottom)); }
  .party-chip { padding: 4px 5px; }
  .party-chip .slot-avatar { flex-basis: 22px; width: 22px; height: 22px; font-size: 0.62rem; }
  .party-chip-info h4 { font-size: 0.56rem; }
  .party-chip-info p { font-size: 0.42rem; }

  .battle-top { grid-template-columns: auto 1fr auto; gap: 8px; padding: 7px 10px; }
  .turn-label { display: none; }
  .turn-token { flex-basis: 20px; width: 20px; height: 20px; font-size: 0.54rem; }
  .battlefield { grid-template-columns: 1fr 1fr; gap: 6px; padding: 7px 8px; }
  .battle-center { display: none; }
  .battle-side { gap: 4px; }
  .side-label span { display: none; }
  .side-label b { font-size: 0.52rem; }
  .unit-grid { gap: 3px; }
  .unit { padding: 5px 5px; gap: 5px; border-radius: 4px; }
  .unit-avatar { flex-basis: 28px; width: 28px; height: 28px; font-size: 0.78rem; }
  .unit-avatar .unit-row { width: 10px; height: 10px; font-size: 0.32rem; }
  .unit-name { font-size: 0.55rem; }
  .unit-meta { display: none; }
  .unit-statuses { gap: 1px; margin-top: 2px; min-height: 9px; }
  .status-chip { font-size: 0.36rem; padding: 1px 2px; }
  .unit-bar { height: 3px; }
  .battle-bottom { grid-template-columns: 1fr; max-height: 38vh; padding: 6px 8px calc(6px + env(safe-area-inset-bottom)); gap: 5px; }
  .active-card { display: none; }
  .battle-log { display: none !important; }
  .action-buttons { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 3px; }
  .action-btn { min-height: 44px; padding: 5px 6px; }
  .action-btn .action-name { font-size: 0.52rem; }
  .action-btn .action-cost { font-size: 0.4rem; }
  .action-note { font-size: 0.48rem; }
  .overlay { padding: 10px; }
  .overlay-card { padding: 18px; max-height: 92vh; }
  .manual-grid { grid-template-columns: 1fr; }
  .toasts { right: 10px; bottom: 10px; left: 10px; }
  .toast { max-width: none; }
}
@media (max-width: 480px) {
  .title-actions .btn { flex: 1 1 100%; }
  .title-features { font-size: 0.58rem; }
  .game-title { font-size: clamp(2.8rem, 16vw, 4.4rem); }
  .create-grid { grid-template-columns: 1fr 1fr; }
  .option-card { min-height: 128px; }
  .option-glyph { flex-basis: 34px; width: 34px; height: 34px; font-size: 1rem; }
  .option-name { font-size: 0.9rem; }
  .option-desc { display: none; }
  .option-tags { margin-top: 6px; }
  .formation-row { grid-template-columns: 1fr; gap: 5px; }
  .formation-row-label { flex-direction: row; gap: 6px; align-items: center; padding: 2px 0; }
  .formation-board { gap: 12px; }
  .slot { min-height: 96px; }
  .party-footer-actions .btn { flex: 1 1 100%; }
  .party-footer-actions { width: 100%; }
  .dungeon-legend { display: none; }
  .battlefield { padding: 4px 4px; }
  .unit { padding: 4px; gap: 3px; }
  .unit-avatar { flex-basis: 24px; width: 24px; height: 24px; font-size: 0.66rem; }
  .unit-name { font-size: 0.48rem; }
  .unit-statuses { display: none; }
  .battle-top-actions .icon-btn { width: 28px; height: 28px; }
  .battle-round-box b { font-size: 1.05rem; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

files.patch:
Index: css/warband.css
===================================================================
--- css/warband.css
+++ css/warband.css
@@ -785,5 +785,643 @@
   backdrop-filter: blur(14px);
 }
 .party-footer-actions { display: flex; flex-wrap: wrap; gap: 8px; justify-content: flex-end; }

-/* __APPEND__ */
+/* ---------- dungeon ---------- */
+.screen-dungeon { background: radial-gradient(ellipse at 50% 30%, rgba(52, 38, 58, 0.22), transparent 62%), #08070c; }
+.dungeon-shell { flex: 1; min-height: 0; display: flex; flex-direction: column; }
+.dungeon-top {
+  display: grid;
+  grid-template-columns: 1fr auto auto;
+  align-items: center;
+  gap: clamp(12px, 2vw, 30px);
+  padding: 13px clamp(14px, 3vw, 42px);
+  border-bottom: 1px solid var(--line-soft);
+  background: rgba(9, 8, 14, 0.66);
+  backdrop-filter: blur(14px);
+  z-index: 3;
+}
+.dungeon-floor h2 { margin: 2px 0 1px; font-family: var(--font-display); font-size: clamp(1.1rem, 2vw, 1.6rem); font-weight: 400; }
+.dungeon-floor p:last-child { font-size: 0.58rem; color: var(--muted-2); max-width: 520px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
+.dungeon-floor .eyebrow { font-size: 0.55rem; }
+.dungeon-objective {
+  text-align: right;
+  padding: 6px 13px;
+  border-left: 1px solid var(--line);
+  border-right: 1px solid var(--line);
+}
+.objective-label { display: block; font-size: 0.48rem; letter-spacing: 0.18em; color: var(--muted-2); text-transform: uppercase; }
+.dungeon-objective b { font-size: 0.8rem; color: var(--gold-bright); letter-spacing: 0.03em; }
+.dungeon-resources { display: flex; align-items: center; gap: 10px; }
+.resource { font-size: 0.58rem; color: var(--muted-2); display: flex; align-items: center; gap: 4px; white-space: nowrap; }
+.resource b { color: var(--gold-bright); font-size: 0.82rem; }
+.dungeon-stage { position: relative; flex: 1; min-height: 0; overflow: hidden; }
+#dungeon-canvas { display: block; width: 100%; height: 100%; }
+.dungeon-vignette {
+  position: absolute;
+  inset: 0;
+  pointer-events: none;
+  background: radial-gradient(ellipse at center, transparent 40%, rgba(4, 3, 7, 0.72) 100%);
+  mix-blend-mode: multiply;
+}
+.dungeon-toast {
+  position: absolute;
+  top: 18px;
+  left: 50%;
+  transform: translateX(-50%);
+  max-width: min(90vw, 520px);
+  padding: 9px 18px;
+  border: 1px solid var(--line);
+  border-radius: 3px;
+  background: rgba(13, 10, 19, 0.92);
+  color: var(--ink-soft);
+  font-size: 0.7rem;
+  letter-spacing: 0.02em;
+  box-shadow: var(--shadow);
+  z-index: 4;
+  text-align: center;
+  animation: toastIn 0.24s ease both;
+}
+.dungeon-toast b { color: var(--gold-bright); }
+@keyframes toastIn { from { opacity: 0; transform: translate(-50%, -6px); } to { opacity: 1; transform: translate(-50%, 0); } }
+.dungeon-legend {
+  position: absolute;
+  left: 16px;
+  bottom: 16px;
+  display: flex;
+  flex-wrap: wrap;
+  gap: 4px 12px;
+  padding: 8px 10px;
+  border: 1px solid var(--line-soft);
+  border-radius: 3px;
+  background: rgba(8, 7, 12, 0.7);
+  backdrop-filter: blur(8px);
+  z-index: 3;
+}
+.dungeon-legend span { display: flex; align-items: center; gap: 5px; font-size: 0.5rem; color: var(--muted-2); letter-spacing: 0.04em; }
+.legend-dot { width: 6px; height: 6px; border-radius: 50%; display: inline-block; box-shadow: 0 0 8px currentColor; }
+.legend-encounter { background: var(--rose); color: var(--rose); }
+.legend-chest { background: var(--gold); color: var(--gold); }
+.legend-shrine { background: var(--teal); color: var(--teal); }
+.legend-stairs { background: var(--violet); color: var(--violet); }
+.minimap-wrap {
+  position: absolute;
+  top: 14px;
+  right: 14px;
+  padding: 6px;
+  border: 1px solid var(--line-soft);
+  border-radius: 3px;
+  background: rgba(8, 7, 12, 0.72);
+  backdrop-filter: blur(8px);
+  z-index: 3;
+}
+#minimap { display: block; width: 150px; height: 104px; opacity: 0.9; }
+.minimap-wrap span { display: block; text-align: center; font-size: 0.45rem; letter-spacing: 0.18em; color: var(--muted-2); margin-top: 3px; }
+.dungeon-controls {
+  position: absolute;
+  right: 18px;
+  bottom: 16px;
+  display: flex;
+  align-items: flex-end;
+  gap: 14px;
+  z-index: 4;
+}
+.dpad { display: grid; grid-template-columns: repeat(3, 38px); grid-template-rows: repeat(3, 38px); gap: 3px; }
+.dpad-btn {
+  border: 1px solid var(--line-soft);
+  border-radius: 4px;
+  background: rgba(15, 12, 22, 0.8);
+  color: var(--muted);
+  display: grid;
+  place-items: center;
+  font-size: 0.7rem;
+  touch-action: none;
+  transition: border-color 0.15s, background 0.15s, color 0.15s;
+}
+.dpad-btn:hover, .dpad-btn.is-held { border-color: var(--gold); color: var(--gold-bright); background: rgba(231, 185, 106, 0.1); }
+.dpad-btn.up { grid-column: 2; grid-row: 1; }
+.dpad-btn.left { grid-column: 1; grid-row: 2; }
+.dpad-btn.down { grid-column: 2; grid-row: 3; }
+.dpad-btn.right { grid-column: 3; grid-row: 2; }
+.interact-btn {
+  width: 62px;
+  height: 62px;
+  border-radius: 50%;
+  border: 1px solid var(--line);
+  background: radial-gradient(circle at 35% 28%, rgba(231, 185, 106, 0.18), rgba(13, 10, 19, 0.9));
+  color: var(--gold-bright);
+  font-family: var(--font-display);
+  font-size: 1.2rem;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  justify-content: center;
+  gap: 1px;
+  box-shadow: 0 0 0 5px rgba(231, 185, 106, 0.035);
+  touch-action: none;
+}
+.interact-btn small { font-family: var(--font-ui); font-size: 0.42rem; letter-spacing: 0.06em; color: var(--muted); }
+.interact-btn:hover { border-color: var(--gold); background: rgba(231, 185, 106, 0.13); }
+.party-bar {
+  display: grid;
+  grid-template-columns: repeat(6, minmax(0, 1fr));
+  gap: 6px;
+  padding: 8px clamp(12px, 3vw, 42px) calc(8px + env(safe-area-inset-bottom));
+  border-top: 1px solid var(--line-soft);
+  background: rgba(9, 8, 14, 0.72);
+  backdrop-filter: blur(12px);
+  z-index: 3;
+}
+.party-chip {
+  display: flex;
+  align-items: center;
+  gap: 7px;
+  padding: 5px 7px;
+  border: 1px solid var(--line-soft);
+  border-radius: 3px;
+  background: rgba(20, 16, 28, 0.55);
+  min-width: 0;
+}
+.party-chip .slot-avatar { flex: 0 0 27px; width: 27px; height: 27px; font-size: 0.75rem; }
+.party-chip-info { min-width: 0; flex: 1; }
+.party-chip-info h4 { font-size: 0.62rem; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
+.party-chip-info p { font-size: 0.46rem; color: var(--muted-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
+.party-chip .mini-bar { margin-top: 3px; height: 4px; }
+.party-chip.is-down { opacity: 0.4; filter: grayscale(0.7); }
+
+/* ---------- battle ---------- */
+.screen-battle { background: radial-gradient(ellipse at 50% 36%, rgba(68, 44, 65, 0.3), transparent 58%), #08070c; }
+.battle-shell { flex: 1; min-height: 0; display: flex; flex-direction: column; }
+.battle-top {
+  display: grid;
+  grid-template-columns: auto 1fr auto;
+  align-items: center;
+  gap: 16px;
+  padding: 10px clamp(12px, 3vw, 38px);
+  border-bottom: 1px solid var(--line-soft);
+  background: rgba(9, 8, 14, 0.7);
+  backdrop-filter: blur(12px);
+  z-index: 4;
+}
+.battle-round-box { display: flex; align-items: baseline; gap: 7px; }
+.battle-round-box span { font-size: 0.48rem; letter-spacing: 0.18em; color: var(--muted-2); }
+.battle-round-box b { font-family: var(--font-display); font-size: 1.35rem; color: var(--gold-bright); font-weight: 400; }
+.turn-order-wrap { display: flex; align-items: center; gap: 10px; min-width: 0; }
+.turn-label { font-size: 0.44rem; letter-spacing: 0.16em; color: var(--muted-2); white-space: nowrap; }
+.turn-order { display: flex; align-items: center; gap: 3px; overflow: hidden; min-width: 0; }
+.turn-token {
+  flex: 0 0 23px;
+  width: 23px;
+  height: 23px;
+  border-radius: 50%;
+  display: grid;
+  place-items: center;
+  font-size: 0.62rem;
+  border: 1px solid var(--line-soft);
+  background: rgba(20, 16, 28, 0.7);
+  color: var(--muted);
+  transition: all 0.2s;
+}
+.turn-token.is-ally { border-color: rgba(121, 224, 192, 0.25); color: var(--teal); }
+.turn-token.is-enemy { border-color: rgba(240, 125, 139, 0.25); color: var(--rose); }
+.turn-token.is-current { transform: scale(1.18); background: var(--gold); color: #1c1308; border-color: var(--gold); box-shadow: 0 0 12px rgba(231, 185, 106, 0.4); }
+.turn-token.is-dead { opacity: 0.22; text-decoration: line-through; }
+.battle-top-actions { display: flex; gap: 5px; }
+.battlefield {
+  flex: 1;
+  min-height: 0;
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) minmax(140px, 0.26fr) minmax(0, 1fr);
+  gap: clamp(6px, 1.4vw, 20px);
+  padding: clamp(8px, 1.6vw, 22px) clamp(10px, 2.4vw, 34px);
+  overflow: hidden;
+}
+.battle-side { min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 7px; }
+.side-label { display: flex; justify-content: space-between; align-items: center; padding: 0 3px; }
+.side-label span { font-size: 0.46rem; letter-spacing: 0.18em; color: var(--muted-2); }
+.side-label b { font-size: 0.6rem; color: var(--ink-soft); font-weight: 500; }
+.enemies-side .side-label { flex-direction: row-reverse; }
+.unit-grid {
+  flex: 1;
+  min-height: 0;
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  grid-template-rows: repeat(3, minmax(0, 1fr));
+  gap: clamp(4px, 0.7vw, 9px);
+}
+.unit {
+  position: relative;
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  min-width: 0;
+  padding: 7px 8px;
+  border: 1px solid var(--line-soft);
+  border-radius: 5px;
+  background: linear-gradient(150deg, rgba(29, 24, 39, 0.75), rgba(11, 9, 17, 0.82));
+  transition: border-color 0.18s, transform 0.18s, box-shadow 0.18s, opacity 0.3s;
+  overflow: hidden;
+}
+.unit::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  pointer-events: none;
+  background: radial-gradient(circle at 10% 0%, var(--unit-glow, rgba(231, 185, 106, 0.1)), transparent 55%);
+}
+.unit.is-ally { border-left: 2px solid rgba(121, 224, 192, 0.55); }
+.unit.is-enemy { border-right: 2px solid rgba(240, 125, 139, 0.55); }
+.unit.is-active { border-color: var(--gold); box-shadow: 0 0 0 1px rgba(231, 185, 106, 0.4), 0 0 24px rgba(231, 185, 106, 0.12); }
+.unit.is-targetable { cursor: crosshair; border-color: var(--rose); box-shadow: 0 0 0 1px rgba(240, 125, 139, 0.5), 0 0 22px rgba(240, 125, 139, 0.18); animation: targetPulse 1.2s ease-in-out infinite; }
+.unit.is-targetable.is-ally { border-color: var(--teal); box-shadow: 0 0 0 1px rgba(121, 224, 192, 0.5), 0 0 22px rgba(121, 224, 192, 0.18); }
