+  .unit { padding: 4px; gap: 3px; }
+  .unit-avatar { flex-basis: 24px; width: 24px; height: 24px; font-size: 0.66rem; }
+  .unit-name { font-size: 0.48rem; }
+  .unit-statuses { display: none; }
+  .battle-top-actions .icon-btn { width: 28px; height: 28px; }
