// Character math: race + class + specialist kit, with no cross-locking.
import {
  BASE_STATS,
  STAT_KEYS,
  RACES,
  CLASSES,
  NAME_POOL,
  raceById,
  classById,
  kitById,
  representativeKit
} from './data.js';

let characterCounter = 0;

export function makeCharacterId() {
  characterCounter += 1;
  return `warband_${Date.now().toString(36)}_${characterCounter}`;
}

export function xpNeeded(level) {
  return 70 + (level - 1) * 55;
}

export function computeCharacter(character) {
  const race = raceById(character.raceId) || RACES[0];
  const cls = classById(character.classId) || CLASSES[0];
  const kit = kitById(cls.id, character.kitId) || representativeKit(cls.id);
  const level = character.level || 1;
  const growth = character.growth || {};

  const stats = {};
  for (const key of STAT_KEYS) {
    stats[key] = (BASE_STATS[key] || 0) + (race.mods[key] || 0) + (cls.mods[key] || 0) + (kit.statMods?.[key] || 0) + (growth[key] || 0);
  }

  let hpMult = 1;
  let defenseMult = 1;
  let speedBonus = 0;
  let critBonus = 0;
  let evadeBonus = 0;
  if (race.trait.id === 'thick_hide') hpMult *= 1.12;
  if (race.trait.id === 'master_craft') defenseMult *= 1.1;
  if (race.trait.id === 'verdant_step') speedBonus += 3;
  if (race.trait.id === 'glide') { speedBonus += 6; critBonus += 5; }
  if (race.trait.id === 'fade') evadeBonus += 6;

  const maxHp = Math.max(1, Math.round((42 + stats.vitality * 6.4 + level * 4) * hpMult));
  const maxAether = Math.max(1, Math.round(10 + stats.intellect * 2.2 + stats.spirit * 2 + level * 2));
  const power = Math.round(10 + stats.might * 2.3 + level * 2.2);
  const spell = Math.round(10 + stats.intellect * 2.2 + stats.spirit * 0.75 + level * 2.2);
  const defense = Math.round((3 + stats.vitality * 1.15 + level * 1.1) * defenseMult);
  const resolve = Math.round(3 + stats.spirit * 1.1 + stats.intellect * 0.4 + level * 1.1);
  const speed = Math.round(10 + stats.agility * 1.9 + stats.presence * 0.35 + level * 0.8 + speedBonus);
  const crit = Math.min(60, Math.round((4 + stats.agility * 0.55 + stats.presence * 0.18 + critBonus) * 10) / 10);
  const evade = Math.min(40, Math.round((2 + stats.agility * 0.42 + evadeBonus) * 10) / 10);

  const allowedWeapons = kit.allowedWeapons?.length ? kit.allowedWeapons : cls.weapons;
  const allowedArmor = kit.allowedArmor?.length ? kit.allowedArmor : cls.armor;
  const equipment = {
    weapon: allowedWeapons[0] || '맨손',
    armor: allowedArmor[0] || '없음'
  };

  return {
    race,
    cls,
    kit,
    level,
    stats,
    derived: { maxHp, maxAether, power, spell, defense, resolve, speed, crit, evade },
    allowedWeapons,
    allowedArmor,
    equipment,
    attackKind: cls.attackKind,
    attackReach: cls.attackReach
  };
}

export function createCharacter({
  name,
  raceId,
  classId,
  kitId,
  level = 1,
  growth = {},
  hp = null,
  aether = null,
  xp = 0
}) {
  const character = {
    id: makeCharacterId(),
    name: (name || '').trim() || '이름 없는 자',
    raceId,
    classId,
    kitId: kitId || representativeKit(classId)?.id,
    level,
    xp,
    growth: { ...growth }
  };
  const computed = computeCharacter(character);
  character.hp = hp == null ? computed.derived.maxHp : Math.min(hp, computed.derived.maxHp);
  character.aether = aether == null ? computed.derived.maxAether : Math.min(aether, computed.derived.maxAether);
  return character;
}

export function levelUpCharacter(character) {
  const computed = computeCharacter(character);
  const keyStats = computed.cls.keyStats;
  character.level += 1;
  for (const key of keyStats) character.growth[key] = (character.growth[key] || 0) + 1;
  character.growth.vitality = (character.growth.vitality || 0) + 1;
  const next = computeCharacter(character);
  character.hp = Math.min(next.derived.maxHp, character.hp + Math.round(next.derived.maxHp * 0.35));
  character.aether = Math.min(next.derived.maxAether, character.aether + Math.round(next.derived.maxAether * 0.35));
  return next;
}

export function grantXp(character, amount) {
  character.xp = (character.xp || 0) + amount;
  let gained = 0;
  while (character.xp >= xpNeeded(character.level)) {
    character.xp -= xpNeeded(character.level);
    levelUpCharacter(character);
    gained += 1;
    if (gained > 20) break;
  }
  return gained;
}

export function restoreCharacter(character) {
  const computed = computeCharacter(character);
  character.hp = computed.derived.maxHp;
  character.aether = computed.derived.maxAether;
  return character;
}

export function healCharacter(character, fraction) {
  const computed = computeCharacter(character);
  character.hp = Math.min(computed.derived.maxHp, character.hp + Math.round(computed.derived.maxHp * fraction));
  return character.hp;
}

export function characterNamePool() {
  return NAME_POOL;
}

export function randomName(used = []) {
  const available = NAME_POOL.filter((n) => !used.includes(n));
  const pool = available.length ? available : NAME_POOL;
  return pool[Math.floor(Math.random() * pool.length)];
}

export function randomCharacter(level = 1, usedNames = [], usedClasses = []) {
  const availableClasses = CLASSES.filter((c) => !usedClasses.includes(c.id));
  const clsPool = availableClasses.length ? availableClasses : CLASSES;
  const cls = clsPool[Math.floor(Math.random() * clsPool.length)];
  const race = RACES[Math.floor(Math.random() * RACES.length)];
  const kit = representativeKit(cls.id);
  const name = randomName(usedNames);
  return createCharacter({ name, raceId: race.id, classId: cls.id, kitId: kit.id, level });
}

export function partyPower(party) {
  return party.reduce((sum, member) => {
    if (!member) return sum;
    const c = computeCharacter(member);
    return sum + c.derived.maxHp + c.derived.power + c.derived.spell;
  }, 0);
}

// Tile dungeon generation, fog of war, minimap and canvas renderer.
import { floorData } from './data.js';

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function hashSeed(value) {
  let h = 2166136261 >>> 0;
  const text = String(value);
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

const DIRS = [
  [1, 0],
  [-1, 0],
  [0, 1],
  [0, -1]
];

function randInt(rand, min, max) {
  return min + Math.floor(rand() * (max - min + 1));
}

function shuffle(rand, list) {
  for (let i = list.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rand() * (i + 1));
    [list[i], list[j]] = [list[j], list[i]];
  }
  return list;
}

function roomOverlaps(a, b, pad = 1) {
  return !(a.x + a.w + pad <= b.x || b.x + b.w + pad <= a.x || a.y + a.h + pad <= b.y || b.y + b.h + pad <= a.y);
}

export function generateDungeon(floor, seed = Date.now()) {
  const rand = mulberry32(typeof seed === 'number' ? seed : hashSeed(seed));
  const width = 31;
  const height = 21;
  const tiles = new Uint8Array(width * height);
  const rooms = [];

  for (let attempt = 0; attempt < 110 && rooms.length < 9; attempt += 1) {
    const w = randInt(rand, 5, 8);
    const h = randInt(rand, 4, 6);
    const x = randInt(rand, 1, width - w - 2);
    const y = randInt(rand, 1, height - h - 2);
    const room = { x, y, w, h, cx: x + Math.floor(w / 2), cy: y + Math.floor(h / 2) };
    if (rooms.some((other) => roomOverlaps(room, other, 1))) continue;
    rooms.push(room);
  }

  // Guarantee a usable layout even on a very unlucky seed.
  if (rooms.length < 5) {
    rooms.length = 0;
    const fallback = [
      { x: 2, y: 2, w: 6, h: 5 },
      { x: 12, y: 2, w: 6, h: 5 },
      { x: 22, y: 3, w: 6, h: 5 },
      { x: 3, y: 13, w: 6, h: 5 },
      { x: 13, y: 12, w: 6, h: 5 },
      { x: 23, y: 12, w: 6, h: 5 }
    ];
    for (const r of fallback) rooms.push({ ...r, cx: r.x + Math.floor(r.w / 2), cy: r.y + Math.floor(r.h / 2) });
  }

  const carve = (x, y) => {
    if (x > 0 && y > 0 && x < width - 1 && y < height - 1) tiles[y * width + x] = 1;
  };

  for (const room of rooms) {
    for (let y = room.y; y < room.y + room.h; y += 1) {
      for (let x = room.x; x < room.x + room.w; x += 1) carve(x, y);
    }
  }

  const connect = (a, b) => {
    let x = a.cx;
    let y = a.cy;
    const horizontalFirst = rand() > 0.5;
    if (horizontalFirst) {
      while (x !== b.cx) { carve(x, y); x += Math.sign(b.cx - x); }
      while (y !== b.cy) { carve(x, y); y += Math.sign(b.cy - y); }
    } else {
      while (y !== b.cy) { carve(x, y); y += Math.sign(b.cy - y); }
      while (x !== b.cx) { carve(x, y); x += Math.sign(b.cx - x); }
    }
    carve(b.cx, b.cy);
  };

  for (let i = 1; i < rooms.length; i += 1) connect(rooms[i - 1], rooms[i]);
  for (let i = 0; i < rooms.length - 2; i += 1) {
    if (rand() < 0.28) connect(rooms[i], rooms[i + 2]);
  }

  const startRoom = rooms[0];
  const start = { x: startRoom.cx, y: startRoom.cy };

  const distanceFrom = (origin) => {
    const dist = new Int16Array(width * height).fill(-1);
    const queue = [origin];
    dist[origin.y * width + origin.x] = 0;
    while (queue.length) {
      const cur = queue.shift();
      const d = dist[cur.y * width + cur.x];
      for (const [dx, dy] of DIRS) {
        const nx = cur.x + dx;
        const ny = cur.y + dy;
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
        if (tiles[ny * width + nx] !== 1) continue;
        const idx = ny * width + nx;
        if (dist[idx] !== -1) continue;
        dist[idx] = d + 1;
        queue.push({ x: nx, y: ny });
      }
    }
    return dist;
  };

  const dist = distanceFrom(start);
  let stairsRoom = rooms[rooms.length - 1];
  let best = -1;
  for (const room of rooms) {
    if (room === startRoom) continue;
    const d = dist[room.cy * width + room.cx];
    if (d > best) { best = d; stairsRoom = room; }
  }
  const stairs = { x: stairsRoom.cx, y: stairsRoom.cy };

  const occupied = new Set([`${start.x},${start.y}`, `${stairs.x},${stairs.y}`]);
  const otherRooms = shuffle(rand, rooms.filter((r) => r !== startRoom && r !== stairsRoom));

  const floorTilesIn = (room) => {
    const list = [];
    for (let y = room.y; y < room.y + room.h; y += 1) {
      for (let x = room.x; x < room.x + room.w; x += 1) {
        if (tiles[y * width + x] === 1 && !occupied.has(`${x},${y}`)) list.push({ x, y });
      }
    }
    return shuffle(rand, list);
  };

  const entities = [];
  const placeEntity = (type, room, extra = {}) => {
    const tilesList = floorTilesIn(room);
    const spot = tilesList.find((t) => !entities.some((e) => e.x === t.x && e.y === t.y));
    if (!spot) return null;
    occupied.add(`${spot.x},${spot.y}`);
    const entity = { id: `${type}_${entities.length}_${Math.floor(rand() * 9999)}`, type, x: spot.x, y: spot.y, ...extra };
    entities.push(entity);
    return entity;
  };

  const encounters = [];
  const isBossFloor = floor === 3 || floor === 5;
  const normalCount = floor === 1 ? 3 : floor === 2 ? 3 : floor === 4 ? 3 : 3;
  for (let i = 0; i < normalCount; i += 1) {
    const room = otherRooms[i % otherRooms.length];
    if (!room) break;
    const elite = floor >= 2 && i === normalCount - 1 && !isBossFloor;
    const entity = placeEntity('encounter', room, { encounterType: elite ? 'elite' : 'normal', cleared: false, floor });
    if (entity) encounters.push(entity);
  }

  if (isBossFloor) {
    const room = otherRooms[Math.min(otherRooms.length - 1, normalCount)] || stairsRoom;
    const entity = placeEntity('encounter', room, {
      encounterType: 'boss',
      bossId: floor === 5 ? 'crown' : 'warden',
      cleared: false,
      floor
    });
    if (entity) encounters.push(entity);
  }

  const chests = [];
  for (let i = 0; i < 2; i += 1) {
    const room = otherRooms[(i + 2) % otherRooms.length];
    if (!room) break;
    const entity = placeEntity('chest', room, { opened: false });
    if (entity) chests.push(entity);
  }

  const shrines = [];
  const shrineRoom = otherRooms[otherRooms.length - 1];
  if (shrineRoom) {
    const entity = placeEntity('shrine', shrineRoom, { used: false });
    if (entity) shrines.push(entity);
  }

  // Decorative torches on room walls. They also give the map a warm rhythm.
  const torches = [];
  for (const room of rooms) {
    const candidates = [
      { x: room.x, y: room.y },
      { x: room.x + room.w - 1, y: room.y },
      { x: room.x, y: room.y + room.h - 1 },
      { x: room.x + room.w - 1, y: room.y + room.h - 1 }
    ];
    for (const c of candidates) {
      if (rand() < 0.7) torches.push({ x: c.x, y: c.y, phase: rand() * Math.PI * 2 });
    }
  }

  return {
    floor,
    seed: typeof seed === 'number' ? seed : hashSeed(seed),
    width,
    height,
    tiles,
    rooms,
    start,
    stairs,
    encounters,
    chests,
    shrines,
    torches,
    theme: floorData(floor),
    dist
  };
}

export function tileAt(dungeon, x, y) {
  if (x < 0 || y < 0 || x >= dungeon.width || y >= dungeon.height) return 0;
  return dungeon.tiles[y * dungeon.width + x];
}

export function isWalkable(dungeon, x, y) {
  return tileAt(dungeon, x, y) === 1;
}

export function entityAt(dungeon, x, y) {
  return [...dungeon.encounters, ...dungeon.chests, ...dungeon.shrines].find((e) => e.x === x && e.y === y && !(e.cleared || e.opened || e.used));
}

export function revealAround(dungeon, pos, radius, visible, explored) {
  visible.clear();
  const r = radius;
  for (let y = pos.y - r; y <= pos.y + r; y += 1) {
    for (let x = pos.x - r; x <= pos.x + r; x += 1) {
      if (x < 0 || y < 0 || x >= dungeon.width || y >= dungeon.height) continue;
      const dx = x - pos.x;
      const dy = y - pos.y;
      if (dx * dx + dy * dy > r * r + r) continue;
      visible.add(`${x},${y}`);
      explored.add(`${x},${y}`);
    }
  }
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

function tileHash(x, y, seed) {
  let h = (x * 374761393 + y * 668265263 + seed * 1442695040) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

export function drawDungeon(ctx, cssWidth, cssHeight, dungeon, view, time, party, leader) {
  const theme = dungeon.theme;
  const tile = Math.max(26, Math.min(54, Math.min(cssWidth / (dungeon.width + 2.5), cssHeight / (dungeon.height + 2.5))));
  const mapW = dungeon.width * tile;
  const mapH = dungeon.height * tile;
  const targetX = party.x * tile + tile / 2 - cssWidth / 2;
  const targetY = party.y * tile + tile / 2 - cssHeight / 2;
  const maxX = Math.max(0, mapW - cssWidth);
  const maxY = Math.max(0, mapH - cssHeight);
  const wantX = mapW <= cssWidth ? (cssWidth - mapW) / 2 : clamp(targetX, 0, maxX);
  const wantY = mapH <= cssHeight ? (cssHeight - mapH) / 2 : clamp(targetY, 0, maxY);
  if (view.camX == null) { view.camX = wantX; view.camY = wantY; }
  view.camX = lerp(view.camX, wantX, 0.16);
  view.camY = lerp(view.camY, wantY, 0.16);
  const camX = view.camX;
  const camY = view.camY;

  ctx.clearRect(0, 0, cssWidth, cssHeight);
  const bg = ctx.createRadialGradient(cssWidth / 2, cssHeight / 2, 20, cssWidth / 2, cssHeight / 2, Math.max(cssWidth, cssHeight) * 0.75);
  bg.addColorStop(0, theme.fog);
  bg.addColorStop(1, '#050409');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, cssWidth, cssHeight);

  const startX = Math.max(0, Math.floor(camX / tile) - 1);
  const endX = Math.min(dungeon.width - 1, Math.ceil((camX + cssWidth) / tile) + 1);
  const startY = Math.max(0, Math.floor(camY / tile) - 1);
  const endY = Math.min(dungeon.height - 1, Math.ceil((camY + cssHeight) / tile) + 1);

  // Ambient torch glow behind the tiles.
  for (const torch of dungeon.torches) {
    const key = `${torch.x},${torch.y}`;
    if (!view.explored.has(key)) continue;
    const sx = torch.x * tile + tile / 2 - camX;
    const sy = torch.y * tile + tile / 2 - camY;
    if (sx < -tile * 4 || sy < -tile * 4 || sx > cssWidth + tile * 4 || sy > cssHeight + tile * 4) continue;
    const flicker = 0.82 + Math.sin(time * 0.004 + torch.phase) * 0.18;
    const glow = ctx.createRadialGradient(sx, sy, 2, sx, sy, tile * 3.2);
    glow.addColorStop(0, `${theme.accent}44`);
    glow.addColorStop(0.45, `${theme.accent}14`);
    glow.addColorStop(1, 'transparent');
    ctx.globalAlpha = flicker;
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(sx, sy, tile * 3.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  for (let y = startY; y <= endY; y += 1) {
    for (let x = startX; x <= endX; x += 1) {
      const key = `${x},${y}`;
      if (!view.explored.has(key)) continue;
      const visible = view.visible.has(key);
      const sx = Math.floor(x * tile - camX);
      const sy = Math.floor(y * tile - camY);
      const isFloor = tileAt(dungeon, x, y) === 1;
      if (isFloor) {
        const alt = (x + y) % 2 === 0;
        ctx.fillStyle = alt ? theme.floor : theme.floorAlt;
        ctx.fillRect(sx, sy, tile + 1, tile + 1);
        const noise = tileHash(x, y, dungeon.seed);
        if (noise > 0.72) {
          ctx.fillStyle = 'rgba(255,255,255,0.025)';
          ctx.fillRect(sx + tile * 0.2, sy + tile * 0.32, tile * 0.55, 1);
          ctx.fillRect(sx + tile * 0.4, sy + tile * 0.62, tile * 0.28, 1);
        }
        ctx.strokeStyle = 'rgba(0,0,0,0.18)';
        ctx.lineWidth = 1;
        ctx.strokeRect(sx + 0.5, sy + 0.5, tile, tile);
        // A faint inner highlight makes the stone read as carved tiles.
        ctx.fillStyle = 'rgba(255,255,255,0.018)';
        ctx.fillRect(sx + 1, sy + 1, tile - 2, 1);
      } else {
        const hasFloorBelow = tileAt(dungeon, x, y + 1) === 1;
        const hasFloorRight = tileAt(dungeon, x + 1, y) === 1;
        ctx.fillStyle = theme.wall;
        ctx.fillRect(sx, sy, tile + 1, tile + 1);
        ctx.fillStyle = 'rgba(0,0,0,0.2)';
        ctx.fillRect(sx, sy + tile * 0.72, tile + 1, tile * 0.28 + 1);
        if (hasFloorBelow) {
          ctx.fillStyle = theme.wallTop;
          ctx.fillRect(sx, sy + tile - 5, tile + 1, 5);
          ctx.fillStyle = 'rgba(0,0,0,0.32)';
          ctx.fillRect(sx, sy + tile, tile + 1, 5);
        }
        if (hasFloorRight) {
          ctx.fillStyle = 'rgba(255,255,255,0.03)';
          ctx.fillRect(sx + tile - 2, sy, 2, tile);
        }
        const n = tileHash(x, y, dungeon.seed + 7);
        if (n > 0.66) {
          ctx.strokeStyle = 'rgba(0,0,0,0.22)';
          ctx.beginPath();
          ctx.moveTo(sx + tile * 0.2, sy + tile * 0.15);
          ctx.lineTo(sx + tile * 0.42, sy + tile * 0.48);
          ctx.lineTo(sx + tile * 0.35, sy + tile * 0.8);
          ctx.stroke();
        }
      }
      if (!visible) {
        ctx.fillStyle = 'rgba(3, 2, 6, 0.64)';
        ctx.fillRect(sx, sy, tile + 1, tile + 1);
      }
    }
  }

  const pulse = 0.7 + Math.sin(time * 0.004) * 0.3;
  const drawWorld = (wx, wy, fn) => {
    const sx = wx * tile + tile / 2 - camX;
    const sy = wy * tile + tile / 2 - camY;
    if (sx < -tile * 2 || sy < -tile * 2 || sx > cssWidth + tile * 2 || sy > cssHeight + tile * 2) return;
    fn(sx, sy);
  };

  for (const torch of dungeon.torches) {
    const key = `${torch.x},${torch.y}`;
    if (!view.visible.has(key)) continue;
    drawWorld(torch.x, torch.y, (sx, sy) => {
      const flicker = 0.7 + Math.sin(time * 0.01 + torch.phase) * 0.3;
      ctx.fillStyle = `rgba(255, 194, 112, ${0.5 + flicker * 0.4})`;
      ctx.beginPath();
      ctx.arc(sx, sy - tile * 0.18, tile * 0.09, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = `rgba(255, 231, 176, ${0.7 * flicker})`;
      ctx.beginPath();
      ctx.arc(sx, sy - tile * 0.22, tile * 0.04, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  for (const chest of dungeon.chests) {
    if (chest.opened) continue;
    const key = `${chest.x},${chest.y}`;
    if (!view.explored.has(key)) continue;
    drawWorld(chest.x, chest.y, (sx, sy) => {
      ctx.globalAlpha = view.visible.has(key) ? 1 : 0.42;
      ctx.fillStyle = '#7b5624';
      ctx.fillRect(sx - tile * 0.2, sy - tile * 0.12, tile * 0.4, tile * 0.28);
      ctx.fillStyle = '#e7b96a';
      ctx.fillRect(sx - tile * 0.2, sy - tile * 0.12, tile * 0.4, tile * 0.08);
      ctx.fillStyle = '#ffe8ad';
      ctx.fillRect(sx - tile * 0.035, sy - tile * 0.02, tile * 0.07, tile * 0.08);
      ctx.globalAlpha = 1;
    });
  }

  for (const shrine of dungeon.shrines) {
    if (shrine.used) continue;
    const key = `${shrine.x},${shrine.y}`;
    if (!view.explored.has(key)) continue;
    drawWorld(shrine.x, shrine.y, (sx, sy) => {
      ctx.globalAlpha = view.visible.has(key) ? 1 : 0.42;
      const glow = ctx.createRadialGradient(sx, sy, 2, sx, sy, tile * 0.8);
      glow.addColorStop(0, 'rgba(121,224,192,0.5)');
      glow.addColorStop(1, 'transparent');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(sx, sy, tile * 0.8, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#79e0c0';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(sx, sy, tile * 0.22, 0, Math.PI * 2);
      ctx.stroke();
      ctx.fillStyle = '#c6ffec';
      ctx.font = `${Math.round(tile * 0.34)}px serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('✦', sx, sy + 1);
      ctx.globalAlpha = 1;
    });
  }

  for (const encounter of dungeon.encounters) {
    if (encounter.cleared) continue;
    const key = `${encounter.x},${encounter.y}`;
    if (!view.explored.has(key)) continue;
    drawWorld(encounter.x, encounter.y, (sx, sy) => {
      const isBoss = encounter.encounterType === 'boss';
      const isElite = encounter.encounterType === 'elite';
      const color = isBoss ? '#ffd479' : isElite ? '#ff9e58' : '#f07d8b';
      const r = tile * (isBoss ? 0.38 : isElite ? 0.3 : 0.24);
      ctx.globalAlpha = view.visible.has(key) ? 1 : 0.45;
      const glow = ctx.createRadialGradient(sx, sy, 1, sx, sy, r * 2.5);
      glow.addColorStop(0, `${color}66`);
      glow.addColorStop(1, 'transparent');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(sx, sy, r * 2.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = color;
      ctx.lineWidth = isBoss ? 2 : 1.2;
      ctx.beginPath();
      ctx.arc(sx, sy, r * (0.9 + pulse * 0.14), 0, Math.PI * 2);
      ctx.stroke();
      ctx.fillStyle = color;
      ctx.font = `${Math.round(tile * (isBoss ? 0.42 : 0.3))}px serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(isBoss ? '♛' : isElite ? '✧' : '✧', sx, sy + 1);
      ctx.globalAlpha = 1;
    });
  }

  const stairsKey = `${dungeon.stairs.x},${dungeon.stairs.y}`;
  if (view.explored.has(stairsKey)) {
    drawWorld(dungeon.stairs.x, dungeon.stairs.y, (sx, sy) => {
      const visible = view.visible.has(stairsKey);
      ctx.globalAlpha = visible ? 1 : 0.48;
      const glow = ctx.createRadialGradient(sx, sy, 2, sx, sy, tile * 0.9);
      glow.addColorStop(0, 'rgba(169,151,255,0.6)');
      glow.addColorStop(1, 'transparent');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(sx, sy, tile * 0.9, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#a997ff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(sx, sy, tile * 0.3, 0, Math.PI * 2);
      ctx.stroke();
      ctx.fillStyle = '#d9ceff';
      ctx.font = `${Math.round(tile * 0.32)}px serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('⇣', sx, sy + 1);
      ctx.globalAlpha = 1;
    });
  }

  // Party torchlight and token.
  const px = party.x * tile + tile / 2 - camX;
  const py = party.y * tile + tile / 2 - camY;
  const light = ctx.createRadialGradient(px, py, 2, px, py, tile * 4.2);
  light.addColorStop(0, 'rgba(255, 223, 164, 0.22)');
  light.addColorStop(0.4, 'rgba(255, 194, 112, 0.08)');
  light.addColorStop(1, 'transparent');
  ctx.fillStyle = light;
  ctx.beginPath();
  ctx.arc(px, py, tile * 4.2, 0, Math.PI * 2);
  ctx.fill();

  if (party.length > 1) {
    for (let i = 1; i < party.length; i += 1) {
      const angle = (Math.PI * 2 * i) / Math.max(1, party.length - 1) + time * 0.0006;
      const radius = tile * 0.34;
      const ox = px + Math.cos(angle) * radius;
      const oy = py + Math.sin(angle) * radius;
      ctx.fillStyle = 'rgba(231,185,106,0.5)';
      ctx.beginPath();
      ctx.arc(ox, oy, tile * 0.055, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.fillStyle = leader?.color || '#e7b96a';
  ctx.beginPath();
  ctx.arc(px, py, tile * 0.27, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255, 242, 211, 0.9)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(px, py, tile * 0.27, 0, Math.PI * 2);
  ctx.stroke();
  ctx.fillStyle = '#160f08';
  ctx.font = `${Math.round(tile * 0.3)}px serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(leader?.glyph || '✧', px, py + 1);

  // Compass hint toward the stairs when they are still unexplored.
  if (!view.explored.has(stairsKey)) {
    const angle = Math.atan2(dungeon.stairs.y - party.y, dungeon.stairs.x - party.x);
    const cx = cssWidth / 2 + Math.cos(angle) * Math.min(cssWidth, cssHeight) * 0.32;
    const cy = cssHeight / 2 + Math.sin(angle) * Math.min(cssWidth, cssHeight) * 0.32;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    ctx.fillStyle = 'rgba(169,151,255,0.5)';
    ctx.beginPath();
    ctx.moveTo(8, 0);
    ctx.lineTo(-5, -4);
    ctx.lineTo(-2, 0);
    ctx.lineTo(-5, 4);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
}

export function drawMinimap(canvas, dungeon, view, party) {
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width;
  const h = canvas.height;
  const theme = dungeon.theme;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = 'rgba(7,6,11,0.82)';
  ctx.fillRect(0, 0, w, h);
  const sx = w / dungeon.width;
  const sy = h / dungeon.height;
  const size = Math.min(sx, sy);
  const ox = (w - dungeon.width * size) / 2;
  const oy = (h - dungeon.height * size) / 2;

  for (let y = 0; y < dungeon.height; y += 1) {
    for (let x = 0; x < dungeon.width; x += 1) {
      const key = `${x},${y}`;
      if (!view.explored.has(key)) continue;
      const isFloor = tileAt(dungeon, x, y) === 1;
      ctx.fillStyle = isFloor ? (view.visible.has(key) ? theme.wallTop : 'rgba(70,60,80,0.35)') : 'rgba(20,16,26,0.5)';
      ctx.fillRect(ox + x * size, oy + y * size, Math.ceil(size), Math.ceil(size));
    }
  }

  const dot = (x, y, color, r = Math.max(1.5, size * 0.28)) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(ox + x * size + size / 2, oy + y * size + size / 2, r, 0, Math.PI * 2);
    ctx.fill();
  };

  for (const e of dungeon.encounters) {
    if (e.cleared) continue;
    if (!view.explored.has(`${e.x},${e.y}`)) continue;
    dot(e.x, e.y, e.encounterType === 'boss' ? '#ffd479' : '#f07d8b', Math.max(1.6, size * 0.28));
  }
  for (const c of dungeon.chests) {
    if (c.opened || !view.explored.has(`${c.x},${c.y}`)) continue;
    dot(c.x, c.y, '#e7b96a', Math.max(1.2, size * 0.2));
  }
  for (const s of dungeon.shrines) {
    if (s.used || !view.explored.has(`${s.x},${s.y}`)) continue;
    dot(s.x, s.y, '#79e0c0', Math.max(1.2, size * 0.2));
  }
  if (view.explored.has(`${dungeon.stairs.x},${dungeon.stairs.y}`)) dot(dungeon.stairs.x, dungeon.stairs.y, '#a997ff', Math.max(2, size * 0.36));
  dot(party.x, party.y, '#fff2d3', Math.max(2.2, size * 0.4));
  ctx.strokeStyle = 'rgba(231,185,106,0.45)';
  ctx.lineWidth = 1;
  ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
}

// 6v6 turn-based battle engine. The UI is intentionally kept outside so the
// same rules can be rendered by any front-end.
import {
  ENEMIES,
  ENCOUNTER_POOLS,
  STATUSES,
  classById,
  representativeKit
} from './data.js';
import { computeCharacter } from './character.js';

const rnd = (min, max) => min + Math.random() * (max - min);
const pick = (list) => list[Math.floor(Math.random() * list.length)];
const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
const roman = ['', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII'];

function statusType(id) {
  return STATUSES[id]?.type || 'debuff';
}

function statusName(id) {
  return STATUSES[id]?.name || id;
}

function statusGlyph(id) {
  return STATUSES[id]?.glyph || '·';
}

export class Battle {
  constructor({ party, floor, encounter, items, callbacks = {} }) {
    this.party = party;
    this.floor = floor;
    this.encounter = encounter;
    this.items = { potions: items?.potions ?? 2, ethers: items?.ethers ?? 1 };
    this.cb = callbacks;
    this.round = 1;
    this.logs = [];
    this.units = [];
    this.queue = [];
    this.activeUid = null;
    this.phase = 'intro';
    this.pendingAction = null;
    this.finished = false;
    this.auto = false;
    this.message = '전투 준비';
    this.stolenGold = 0;
    this.result = null;
    this.buildAllies();
    this.buildEnemies();
  }

  buildAllies() {
    this.party.forEach((character, index) => {
      const c = computeCharacter(character);
      const row = index < 2 ? 'front' : index < 4 ? 'mid' : 'back';
      const maxHp = c.derived.maxHp;
      const maxAether = c.derived.maxAether;
      const unit = {
        uid: `ally_${character.id}`,
        side: 'ally',
        character,
        name: character.name,
        level: character.level,
        row,
        slot: index,
        raceId: character.raceId,
        classId: character.classId,
        kitId: character.kitId,
        raceName: c.race.name,
        className: c.cls.name,
        kitName: c.kit.name,
        glyph: c.cls.glyph,
        color: c.cls.color,
        stats: c.stats,
        maxHp,
        hp: clamp(character.hp ?? maxHp, 1, maxHp),
        maxAether,
        aether: clamp(character.aether ?? maxAether, 0, maxAether),
        power: c.derived.power,
        spell: c.derived.spell,
        defense: c.derived.defense,
        resolve: c.derived.resolve,
        speed: c.derived.speed,
        crit: c.derived.crit,
        evade: c.derived.evade,
        attackKind: c.attackKind,
        attackReach: c.attackReach,
        ability: c.cls.ability,
        kitAbility: c.kit.ability,
        statuses: [],
        cooldowns: {},
        alive: true,
        boss: false,
        trait: c.race.trait.id,
        veilUsed: false,
        deathlessUsed: false,
        guardUsed: false
      };
      this.units.push(unit);
    });
  }

  buildEnemies() {
    const pool = ENCOUNTER_POOLS[Math.min(5, this.floor)] || ENCOUNTER_POOLS[5];
    const isBoss = this.encounter?.encounterType === 'boss';
    const isElite = this.encounter?.encounterType === 'elite';
    const bossId = this.encounter?.bossId || (this.floor === 5 ? 'crown' : 'warden');
    const list = [];
    if (isBoss) {
      list.push({ id: bossId, boss: true });
      for (let i = 0; i < 5; i += 1) list.push({ id: pool[i % pool.length], boss: false });
    } else {
      for (let i = 0; i < 6; i += 1) list.push({ id: pool[i % pool.length], boss: false });
    }

    const counts = {};
    list.forEach((entry, index) => {
      const template = ENEMIES[entry.id] || ENEMIES.wisp;
      counts[entry.id] = (counts[entry.id] || 0) + 1;
      const level = Math.max(1, this.floor + (entry.boss ? 2 : 0) + (isElite ? 1 : 0));
      const scale = 1 + (this.floor - 1) * 0.12 + (isElite ? 0.18 : 0);
      const maxHp = Math.round((52 + this.floor * 17) * template.hp * (entry.boss ? 1 : 1) * scale);
      const row = entry.boss ? 'front' : index < 3 ? 'front' : 'back';
      const unit = {
        uid: `enemy_${index}_${entry.id}`,
        side: 'enemy',
        enemyId: entry.id,
        name: `${template.name}${counts[entry.id] > 1 ? ` ${roman[Math.min(8, counts[entry.id])]}` : ''}`,
        level,
        row,
        slot: index,
        raceName: '',
        className: template.role,
        kitName: '',
        glyph: template.glyph,
        color: template.color,
        maxHp,
        hp: maxHp,
        maxAether: 999,
        aether: 999,
        power: Math.round((17 + this.floor * 6.5) * template.power * scale),
        spell: Math.round((17 + this.floor * 6.5) * template.spell * scale),
        defense: Math.round((4 + this.floor * 3.2) * template.defense * scale),
        resolve: Math.round((4 + this.floor * 2.8) * template.resolve * scale),
        speed: Math.round((11 + this.floor * 1.6) * template.speed),
        crit: Math.round((4 + this.floor * 0.5) * 10) / 10,
        evade: Math.round((2 + this.floor * 0.35) * 10) / 10,
        attackKind: template.spell > template.power ? 'magic' : 'physical',
        attackReach: template.spell > template.power ? 'any' : 'front',
        ability: template.ability || null,
        abilities: template.abilities || (template.ability ? [template.ability] : []),
        statuses: [],
        cooldowns: {},
        alive: true,
        boss: !!entry.boss,
        undead: ['wisp', 'wraith', 'crown'].includes(entry.id),
        trait: null
      };
      this.units.push(unit);
    });
  }

  start() {
    this.addLog(`<b>${this.floor}층</b>의 공허 존재들이 길을 막아섭니다.`, 'system');
    this.addLog('전투가 시작됩니다.', 'system');
    this.buildQueue();
    this.phase = 'intro';
    this.cb.onUpdate?.();
    setTimeout(() => this.nextTurn(), 480);
  }

  buildQueue() {
    this.queue = this.units
      .filter((u) => u.alive)
      .map((u) => ({ uid: u.uid, speed: u.speed + rnd(0, 3) + (this.getStatus(u, 'haste') ? 12 : 0) - (this.getStatus(u, 'slow') ? 8 : 0) }))
      .sort((a, b) => b.speed - a.speed)
      .map((u) => u.uid);
  }

  getUnit(uid) {
    return this.units.find((u) => u.uid === uid) || null;
  }

  getActive() {
    return this.getUnit(this.activeUid);
  }

  getAlive(side) {
    return this.units.filter((u) => u.side === side && u.alive);
  }

  getStatus(unit, id) {
    return unit.statuses.find((s) => s.id === id) || null;
  }

  hasStatus(unit, id) {
    return !!this.getStatus(unit, id);
  }

  addLog(text, tone = '') {
    this.logs.push({ text, tone, round: this.round });
    if (this.logs.length > 80) this.logs.shift();
    this.cb.onLog?.({ text, tone, round: this.round });
  }

  setMessage(text) {
    this.message = text;
    this.cb.onUpdate?.();
  }

  nextTurn() {
    if (this.finished) return;
    if (this.checkEnd()) return;
    if (!this.queue.length) {
      this.round += 1;
      this.buildQueue();
      this.addLog(`<b>라운드 ${this.round}</b>`, 'system');
      this.cb.onFx?.({ type: 'round', round: this.round });
      this.cb.onUpdate?.();
    }
    const uid = this.queue.shift();
    const unit = this.getUnit(uid);
    if (!unit || !unit.alive) {
      setTimeout(() => this.nextTurn(), 60);
      return;
    }
    this.activeUid = uid;
    this.pendingAction = null;
    this.startOfTurn(unit);
    if (this.finished) return;
    if (!unit.alive) {
      this.finishTurn(unit);
      return;
    }
    const stunned = this.hasStatus(unit, 'stun');
    if (stunned) {
      this.phase = 'resolving';
      this.setMessage(`${unit.name}은(는) 기절해 행동하지 못합니다.`);
      this.addLog(`<span class="${unit.side}">${unit.name}</span> 기절`, 'control');
      this.cb.onFx?.({ type: 'status', uid: unit.uid, text: '기절' });
      this.cb.onUpdate?.();
      setTimeout(() => this.finishTurn(unit), 720);
      return;
    }
    if (unit.side === 'ally') {
      this.phase = 'select';
      this.setMessage(`${unit.name}의 턴입니다.`);
      this.cb.onUpdate?.();
      if (this.auto) setTimeout(() => this.autoAlly(unit), 420);
    } else {
      this.phase = 'enemy';
      this.setMessage(`${unit.name}이(가) 노리고 있습니다.`);
      this.cb.onUpdate?.();
      setTimeout(() => this.enemyTurn(unit), 520);
    }
  }

  startOfTurn(unit) {
    // Cooldowns tick down at the start of the unit's own turn.
    for (const key of Object.keys(unit.cooldowns)) {
      unit.cooldowns[key] = Math.max(0, unit.cooldowns[key] - 1);
    }
    if (unit.trait === 'tidal_grace') {
      const heal = Math.round(unit.maxHp * 0.03);
      this.healUnit(unit, heal, null, '조수의 은총');
    }
    for (const status of [...unit.statuses]) {
      if (status.id === 'poison' || status.id === 'burn') {
        const amount = Math.max(1, Math.round(unit.maxHp * status.value));
        this.applyRawDamage(unit, amount, status.id === 'burn' ? '화상' : '독');
      } else if (status.id === 'regen') {
        const amount = Math.max(1, Math.round(unit.maxHp * status.value));
        this.healUnit(unit, amount, null, '재생');
      }
    }
    if (!unit.alive) return;
    if (unit.trait === 'deathless' && unit.hp <= 0) unit.hp = 1;
  }

  finishTurn(unit) {
    if (this.finished) return;
    if (unit?.alive) {
      for (const status of [...unit.statuses]) {
        if (status.id === 'shield') continue;
        status.turns -= 1;
        if (status.turns <= 0) {
          unit.statuses = unit.statuses.filter((s) => s !== status);
        }
      }
    }
    this.activeUid = null;
    this.pendingAction = null;
    this.cb.onUpdate?.();
    if (this.checkEnd()) return;
    setTimeout(() => this.nextTurn(), 230);
  }

  checkEnd() {
    if (this.finished) return true;
    const alliesAlive = this.getAlive('ally').length;
    const enemiesAlive = this.getAlive('enemy').length;
    if (enemiesAlive === 0) {
      this.finish('victory');
      return true;
    }
    if (alliesAlive === 0) {
      this.finish('defeat');
      return true;
    }
    return false;
  }

  finish(result) {
    if (this.finished) return;
    this.finished = true;
    this.phase = result;
    const enemies = this.units.filter((u) => u.side === 'enemy');
    const boss = enemies.some((u) => u.boss);
    const baseXp = enemies.reduce((sum, u) => sum + (u.boss ? 120 : 28 + this.floor * 6), 0);
    const xp = Math.round(baseXp * (result === 'victory' ? 1 : 0.25));
    const gold = Math.round(enemies.reduce((sum, u) => sum + (u.boss ? 120 : 12 + this.floor * 4), 0) * (result === 'victory' ? 1 : 0.3)) + this.stolenGold;
    const potionDrop = result === 'victory' && Math.random() < (boss ? 0.85 : 0.28) ? 1 : 0;
    const etherDrop = result === 'victory' && Math.random() < (boss ? 0.65 : 0.18) ? 1 : 0;
    this.result = {
      result,
      xp,
      gold,
      potions: potionDrop,
      ethers: etherDrop,
      boss,
      floor: this.floor,
      round: this.round,
      units: this.units.map((u) => ({ uid: u.uid, side: u.side, hp: u.hp, maxHp: u.maxHp, aether: u.aether, maxAether: u.maxAether, alive: u.alive }))
    };
    if (result === 'victory') {
      this.addLog('<b>전투 승리.</b>', 'system');
      this.setMessage('승리했습니다.');
      this.cb.onFx?.({ type: 'victory' });
      setTimeout(() => this.cb.onEnd?.(this.result), 900);
    } else {
      this.addLog('<b>원정대가 쓰러졌습니다.</b>', 'system');
      this.setMessage('패배...');
      this.cb.onFx?.({ type: 'defeat' });
      setTimeout(() => this.cb.onEnd?.(this.result), 1100);
    }
    this.cb.onUpdate?.();
  }

  // -------------------------------------------------------------------------
  // Actions and targeting
  // -------------------------------------------------------------------------

  getPlayerActions() {
    const unit = this.getActive();
    if (!unit || unit.side !== 'ally' || this.phase !== 'select') return [];
    const ability = unit.ability;
    const kitAbility = unit.kitAbility;
    const actions = [
      {
        id: 'basic',
        name: '공격',
        icon: '⚔',
        cost: 0,
        cooldown: 0,
        target: 'enemy',
        kind: unit.attackKind,
        power: 1,
        reach: unit.attackReach,
        desc: unit.attackKind === 'physical' ? '무기로 적을 공격합니다.' : '마법으로 적을 공격합니다.',
        disabled: false,
        key: '1'
      }
    ];
    if (ability) {
      const cd = unit.cooldowns[ability.id] || 0;
      actions.push({
        ...ability,
        id: ability.id,
        icon: '✦',
        name: ability.name,
        desc: ability.desc,
        cost: this.costFor(unit, ability),
        disabled: cd > 0 || unit.aether < this.costFor(unit, ability),
        reason: cd > 0 ? `재사용 ${cd}턴` : unit.aether < this.costFor(unit, ability) ? '에테르 부족' : '',
        key: '2'
      });
    }
    if (kitAbility && kitAbility.id) {
      const cd = unit.cooldowns[kitAbility.id] || 0;
      actions.push({
        ...kitAbility,
        id: kitAbility.id,
        icon: '◆',
        name: kitAbility.name,
        desc: kitAbility.desc,
        cost: this.costFor(unit, kitAbility),
        disabled: cd > 0 || unit.aether < this.costFor(unit, kitAbility),
        reason: cd > 0 ? `재사용 ${cd}턴` : unit.aether < this.costFor(unit, kitAbility) ? '에테르 부족' : '',
        key: '3'
      });
    }
    actions.push({
      id: 'defend',
      name: '방어',
      icon: '◈',
      cost: 0,
      cooldown: 0,
      target: 'self',
      kind: 'buff',
      desc: '이번 턴 받는 피해를 40% 줄이고 에테르를 10% 회복합니다.',
      disabled: false,
      key: '4'
    });
    actions.push({
      id: 'potion',
      name: '회복약',
      icon: '✚',
      cost: 0,
      cooldown: 0,
      target: 'ally',
      kind: 'heal',
      power: 0.35,
      desc: `아군 하나의 생명력을 35% 회복합니다. 남은 수: ${this.items.potions}`,
      disabled: this.items.potions <= 0,
      reason: this.items.potions <= 0 ? '회복약 없음' : '',
      key: '5',
      item: true
    });
    actions.push({
      id: 'ether',
      name: '에테르약',
      icon: '✦',
      cost: 0,
      cooldown: 0,
      target: 'ally',
      kind: 'ether',
      desc: `아군 하나의 에테르를 30 회복합니다. 남은 수: ${this.items.ethers}`,
      disabled: this.items.ethers <= 0,
      reason: this.items.ethers <= 0 ? '에테르약 없음' : '',
      key: '6',
      item: true
    });
    return actions;
  }

  costFor(unit, ability) {
    const base = ability.cost || 0;
    return unit.trait === 'runic_echo' ? Math.max(0, Math.round(base * 0.85)) : base;
  }

  beginAction(actionId) {
    if (this.phase !== 'select') return false;
    const unit = this.getActive();
    if (!unit || unit.side !== 'ally') return false;
    if (actionId === 'cancel') {
      this.pendingAction = null;
      this.phase = 'select';
      this.cb.onUpdate?.();
      return true;
    }
    const action = this.getPlayerActions().find((a) => a.id === actionId);
    if (!action || action.disabled) return false;
    if (actionId === 'defend') {
      this.executeDefend(unit);
      return true;
    }
    if (action.target === 'self' || action.target === 'allEnemies' || action.target === 'allAllies' || action.target === 'randomEnemies' || action.target === 'randomAllies') {
      this.executeAction(unit, action, null);
      return true;
    }
    const targets = this.getValidTargets(unit, action);
    if (!targets.length) {
      this.setMessage('유효한 대상이 없습니다.');
      return false;
    }
    if (targets.length === 1) {
      this.executeAction(unit, action, targets[0].uid);
      return true;
    }
    this.pendingAction = action;
    this.phase = 'target';
    this.setMessage('대상을 선택하세요.');
    this.cb.onUpdate?.();
    return true;
  }

  selectTarget(uid) {
    if (this.phase !== 'target' || !this.pendingAction) return false;
    const unit = this.getActive();
    if (!unit) return false;
    const targets = this.getValidTargets(unit, this.pendingAction);
    if (!targets.some((t) => t.uid === uid)) return false;
    const action = this.pendingAction;
    this.pendingAction = null;
    this.executeAction(unit, action, uid);
    return true;
  }

  cancelTarget() {
    if (this.phase !== 'target') return false;
    this.pendingAction = null;
    this.phase = 'select';
    this.setMessage(`${this.getActive()?.name || ''}의 턴입니다.`);
    this.cb.onUpdate?.();
    return true;
  }

  toggleAuto() {
    this.auto = !this.auto;
    this.cb.onUpdate?.();
    if (this.auto && this.phase === 'select') setTimeout(() => this.autoAlly(this.getActive()), 200);
  }

  getValidTargets(unit, action) {
    const opposing = unit.side === 'ally' ? 'enemy' : 'ally';
    const same = unit.side;
    const targetType = action.target || (action.kind === 'heal' || action.kind === 'buff' ? 'ally' : 'enemy');
    let pool = [];
    if (targetType === 'enemy' || targetType === 'allEnemies' || targetType === 'randomEnemies') pool = this.getAlive(opposing);
    else if (targetType === 'ally' || targetType === 'allAllies' || targetType === 'randomAllies') pool = this.getAlive(same);
    else if (targetType === 'self') pool = [unit];
    else pool = this.getAlive(opposing);
    if (targetType === 'enemy' && (action.reach === 'front' || (!action.reach && action.kind === 'physical'))) {
      const front = pool.filter((u) => u.row === 'front');
      if (front.length) pool = front;
    }
    return pool;
  }

  resolveTargets(unit, action, targetUid, hitIndex = 0) {
    const targetType = action.target || 'enemy';
    if (targetUid) {
      const target = this.getUnit(targetUid);
      return target?.alive ? [target] : [];
    }
    if (targetType === 'self') return [unit];
    if (targetType === 'allEnemies' || targetType === 'allAllies') {
      return this.getValidTargets(unit, action);
    }
    if (targetType === 'randomEnemies' || targetType === 'randomAllies') {
      const pool = this.getValidTargets(unit, action);
      return pool.length ? [pick(pool)] : [];
    }
    const pool = this.getValidTargets(unit, action);
    return pool.length ? [pool[0]] : [];
  }

  // -------------------------------------------------------------------------
  // Execution
  // -------------------------------------------------------------------------

  executeDefend(unit) {
    this.phase = 'resolving';
    this.setMessage(`${unit.name}이(가) 방어 태세를 취합니다.`);
    this.addLog(`<span class="ally">${unit.name}</span> 방어`, 'system');
    this.applyStatus(unit, { id: 'guard', turns: 1, value: 0.4 }, unit);
    unit.aether = Math.min(unit.maxAether, unit.aether + Math.round(unit.maxAether * 0.1));
    this.cb.onFx?.({ type: 'status', uid: unit.uid, text: '방어' });
    this.cb.onUpdate?.();
    setTimeout(() => this.finishTurn(unit), 500);
  }

  executeAction(unit, action, targetUid) {
    if (this.finished) return;
    this.phase = 'resolving';
    this.pendingAction = null;
    const cost = action.item ? 0 : this.costFor(unit, action);
    if (unit.aether < cost) {
      this.setMessage('에테르가 부족합니다.');
      this.phase = 'select';
      this.cb.onUpdate?.();
      return;
    }
    unit.aether -= cost;
    if (!action.item) unit.cooldowns[action.id] = action.cooldown || 0;

    const targetName = targetUid ? this.getUnit(targetUid)?.name : null;
    const targetText = targetName ? ` → ${targetName}` : '';
    this.addLog(`<span class="${unit.side}">${unit.name}</span> · <b>${action.name}</b>${targetText}`, 'action');
    this.setMessage(`${unit.name} · ${action.name}`);
    this.cb.onFx?.({ type: 'cast', uid: unit.uid, action });
    this.cb.onUpdate?.();

    let extraTurn = false;
    const targets = this.resolveTargets(unit, action, targetUid);
    const hits = action.hits || 1;
    const isRandom = action.target === 'randomEnemies' || action.target === 'randomAllies';

    if (action.item) {
      if (action.id === 'potion') {
        this.items.potions = Math.max(0, this.items.potions - 1);
        const target = targets[0] || unit;
        const amount = Math.round(target.maxHp * action.power);
        this.healUnit(target, amount, unit, '회복약');
        this.cb.onItemsChange?.({ ...this.items });
      } else if (action.id === 'ether') {
        this.items.ethers = Math.max(0, this.items.ethers - 1);
        const target = targets[0] || unit;
        target.aether = Math.min(target.maxAether, target.aether + 30);
        this.cb.onFx?.({ type: 'aether', uid: target.uid, amount: 30 });
        this.cb.onItemsChange?.({ ...this.items });
      }
      this.cb.onUpdate?.();
      setTimeout(() => this.finishTurn(unit), 520);
      return;
    }

    if (action.kind === 'heal') {
      const healTargets = action.target === 'allAllies' || action.target === 'allEnemies'
        ? this.getValidTargets(unit, action)
        : targets;
      for (const target of healTargets) {
        const amount = Math.round(this.spellPower(unit) * (action.power || 1) + target.maxHp * (action.heal || 0));
        this.healUnit(target, amount, unit, action.name);
        if (action.statuses?.length) {
          for (const s of action.statuses) this.applyStatus(target, s, unit);
        } else if (action.status) {
          this.applyStatus(target, action.status, unit);
        }
        if (action.cleanse) this.cleanse(target, action.cleanse);
      }
      if (action.special === 'undead_bane') {
        for (const enemy of this.getAlive(unit.side === 'ally' ? 'enemy' : 'ally')) {
          if (enemy.undead) {
            const dmg = Math.round(this.spellPower(unit) * 0.55);
            this.dealDamage(unit, enemy, { ...action, kind: 'magic', power: 0.55, status: null, statuses: null }, { bonus: 1.25 });
          }
        }
      }
    } else if (action.kind === 'buff' || action.kind === 'debuff') {
      const effectTargets = action.target === 'allEnemies' || action.target === 'allAllies'
        ? this.getValidTargets(unit, action)
        : targets;
      for (const target of effectTargets) {
        if (action.statuses?.length) {
          for (const s of action.statuses) this.applyStatus(target, s, unit);
        } else if (action.status) {
          this.applyStatus(target, action.status, unit);
        }
        if (action.heal) {
          const amount = Math.round(target.maxHp * action.heal);
          this.healUnit(target, amount, unit, action.name);
        }
        if (action.cleanse) this.cleanse(target, action.cleanse);
      }
      if (action.special === 'ashen_aegis') {
        for (const enemy of this.getAlive(unit.side === 'ally' ? 'enemy' : 'ally')) {
          this.applyStatus(enemy, { id: 'taunt', turns: 2, value: 1, source: unit.uid }, unit);
        }
      }
    } else {
      const hitTargets = isRandom ? [] : targets;
      for (let hit = 0; hit < hits; hit += 1) {
        const hitTarget = isRandom ? this.resolveTargets(unit, action, null, hit)[0] : hitTargets[hit % Math.max(1, hitTargets.length)];
        if (!hitTarget) continue;
        const beforeHp = hitTarget.hp;
        let bonus = 1;
        if (action.special === 'marked_bonus' && this.hasStatus(hitTarget, 'mark')) bonus *= 1.2;
        if (action.special === 'shadow_strike' && hitTarget.hp <= hitTarget.maxHp * 0.5) bonus *= 1.5;
        if (action.special === 'undead_bane' && hitTarget.undead) bonus *= 1.25;
        if (unit.trait === 'cinder_blood' && unit.hp <= unit.maxHp * 0.5) bonus *= 1.15;
        if (unit.kitId === 'nightglass_cutpurse') bonus *= 1.0;
        const critBonus = action.special === 'shadow_strike' ? 30 : 0;
        const dealt = this.dealDamage(unit, hitTarget, action, {
          bonus,
          pierce: action.pierce || 0,
          critBonus,
          sourceName: action.name
        });
        if (action.special === 'execute_chain' && !hitTarget.alive) extraTurn = true;
        if (action.special === 'steal' && dealt > 0) {
          const stolen = 8 + this.floor * 2;
          this.stolenGold += stolen;
          this.cb.onFx?.({ type: 'gold', amount: stolen });
        }
        if (action.special === 'ember_cascade' && dealt > 0 && this.lastDamageCrit) {
          unit.aether = Math.min(unit.maxAether, unit.aether + 3);
        }
        if (action.statuses?.length) {
          for (const s of action.statuses) if (hitTarget.alive) this.applyStatus(hitTarget, s, unit);
        } else if (action.status && hitTarget.alive) {
          this.applyStatus(hitTarget, action.status, unit);
        }
        if (action.special === 'dispel' && hitTarget.alive) this.dispel(hitTarget);
        if (action.special === 'steal' && dealt > 0 && beforeHp > 0) {
          // Stealing is intentionally small and shown in the result screen.
        }
      }
    }

    if (action.selfStatus) this.applyStatus(unit, action.selfStatus, unit);
    if (action.cleanse) this.cleanse(unit, action.cleanse);
    if (action.special === 'momentum') this.applyStatus(unit, { id: 'powerUp', turns: 1, value: 0.2 }, unit);
    if (action.special === 'wild_echo' && Math.random() < 0.2) {
      this.addLog('주문이 메아리칩니다!', 'system');
      setTimeout(() => {
        if (this.finished) return;
        const echoTarget = this.getAlive(unit.side === 'ally' ? 'enemy' : 'ally');
        if (echoTarget.length) {
          const target = pick(echoTarget);
          this.dealDamage(unit, target, { ...action, power: (action.power || 1) * 0.5, status: null, statuses: null }, { bonus: 1 });
          this.cb.onUpdate?.();
        }
      }, 260);
    }

    this.cb.onUpdate?.();
    if (this.checkEnd()) return;
    const delay = 540;
    if (extraTurn && unit.alive) {
      this.addLog(`${unit.name}의 처형 연쇄! 추가 행동.`, 'system');
      this.queue.unshift(unit.uid);
      this.activeUid = null;
      setTimeout(() => this.nextTurn(), delay);
    } else {
      setTimeout(() => this.finishTurn(unit), delay);
    }
  }

  spellPower(unit) {
    return Math.max(unit.spell, unit.power * 0.7);
  }

  // -------------------------------------------------------------------------
  // Damage, healing and statuses
  // -------------------------------------------------------------------------

  dealDamage(attacker, defender, action, opts = {}) {
    this.lastDamageCrit = false;
    if (!defender.alive) return 0;
    const trueDamage = !!opts.trueDamage;
    if (!trueDamage) {
      let evade = defender.evade + (this.hasStatus(defender, 'evadeUp') ? 20 : 0);
      if (defender.trait === 'umbral_veil' && !defender.veilUsed) {
        defender.veilUsed = true;
        this.cb.onFx?.({ type: 'miss', uid: defender.uid, text: '그림자 장막' });
        this.addLog(`${defender.name}의 그림자 장막이 공격을 삼켰습니다.`, 'system');
        return 0;
      }
      if (Math.random() * 100 < evade) {
        this.cb.onFx?.({ type: 'miss', uid: defender.uid, text: '회피' });
        this.addLog(`${defender.name} 회피`, 'system');
        return 0;
      }
    }

    const kind = action.kind || 'physical';
    const power = action.power || 1;
    let base = 0;
    let defense = 0;
    if (kind === 'physical') {
      base = attacker.power * power;
      defense = defender.defense;
    } else if (kind === 'magic') {
      base = attacker.spell * power;
      defense = defender.resolve;
    } else {
      base = (attacker.power * power + attacker.spell * (action.magicPower || 0.8)) * 0.82;
      defense = (defender.defense + defender.resolve) * 0.55;
    }
    const pierce = clamp(opts.pierce || 0, 0, 0.9);
    let raw = Math.max(1, base - defense * (1 - pierce) * 0.55);

    const powerUp = this.getStatus(attacker, 'powerUp');
    const weaken = this.getStatus(attacker, 'weaken');
    const defenseUp = this.getStatus(defender, 'defenseUp');
    const mark = this.getStatus(defender, 'mark');
    const shock = this.getStatus(defender, 'shock');
    const guard = this.getStatus(defender, 'guard');
    if (powerUp) raw *= 1 + powerUp.value;
    if (weaken) raw *= 1 - weaken.value;
    if (defenseUp) raw *= 1 - defenseUp.value * 0.65;
    if (mark) raw *= 1 + mark.value;
    if (shock && kind !== 'physical') raw *= 1 + shock.value;
    if (guard) raw *= 1 - guard.value;
    if (defender.trait === 'bedrock' && kind === 'physical') raw *= 0.85;
    if (opts.bonus) raw *= opts.bonus;

    let critChance = attacker.crit + (opts.critBonus || 0);
    const critUp = this.getStatus(attacker, 'critUp');
    if (critUp) critChance += critUp.value * 100;
    if (attacker.kitId === 'wild_ember' && kind === 'magic') critChance += 25;
    if (attacker.kitId === 'nightglass_cutpurse') critChance += 25;
    const crit = Math.random() * 100 < critChance;
    if (crit) raw *= 1.65;
    raw *= rnd(0.92, 1.08);
    let amount = Math.max(1, Math.round(raw));

    const shield = this.getStatus(defender, 'shield');
    if (shield?.amount > 0) {
      const absorbed = Math.min(shield.amount, amount);
      shield.amount -= absorbed;
      amount -= absorbed;
      if (shield.amount <= 0) defender.statuses = defender.statuses.filter((s) => s !== shield);
      if (absorbed > 0) {
        this.cb.onFx?.({ type: 'shield', uid: defender.uid, amount: absorbed });
        this.addLog(`${defender.name}의 보호막이 ${absorbed} 피해를 흡수했습니다.`, 'system');
      }
    }

    if (amount > 0) {
      defender.hp = Math.max(0, defender.hp - amount);
      if (defender.hp <= 0) {
        if (defender.trait === 'deathless' && !defender.deathlessUsed) {
          defender.deathlessUsed = true;
          defender.hp = 1;
          this.addLog(`${defender.name}이(가) 불사의 고집으로 버팁니다.`, 'system');
          this.cb.onFx?.({ type: 'status', uid: defender.uid, text: '불사의 고집' });
        } else {
          defender.alive = false;
          defender.hp = 0;
          this.addLog(`<span class="${defender.side}">${defender.name}</span> 쓰러짐`, 'system');
        }
      }
      this.cb.onFx?.({
        type: 'damage',
        uid: defender.uid,
        amount,
        crit,
        killed: !defender.alive,
        kind,
        source: attacker.uid
      });
      this.addLog(`${defender.name}에게 <b>${amount}</b> 피해${crit ? ' · 치명타' : ''}`, 'damage');
      if (crit) this.cb.onFx?.({ type: 'crit', uid: defender.uid });
      const lifesteal = this.getStatus(attacker, 'lifesteal');
      if (lifesteal) this.healUnit(attacker, Math.round(amount * lifesteal.value), null, '흡혈');
    }
    this.lastDamageCrit = crit;
    return amount;
  }

  applyRawDamage(target, amount, sourceName) {
    if (!target.alive) return;
    const shield = this.getStatus(target, 'shield');
    let remaining = amount;
    if (shield?.amount > 0) {
      const absorbed = Math.min(shield.amount, remaining);
      shield.amount -= absorbed;
      remaining -= absorbed;
      if (shield.amount <= 0) target.statuses = target.statuses.filter((s) => s !== shield);
    }
    if (remaining > 0) {
      target.hp = Math.max(0, target.hp - remaining);
      if (target.hp <= 0) {
        if (target.trait === 'deathless' && !target.deathlessUsed) {
          target.deathlessUsed = true;
          target.hp = 1;
        } else {
          target.alive = false;
          this.addLog(`<span class="${target.side}">${target.name}</span> 쓰러짐`, 'system');
        }
      }
      this.cb.onFx?.({ type: 'damage', uid: target.uid, amount: remaining, crit: false, killed: !target.alive, kind: 'dot' });
      this.addLog(`${target.name} · ${sourceName} <b>${remaining}</b>`, 'damage');
    }
  }

  healUnit(target, amount, source, sourceName = '회복') {
    if (!target?.alive) return 0;
    let final = Math.max(0, Math.round(amount));
    if (source?.trait === 'dawnlight') final = Math.round(final * 1.2);
    if (source?.kitId === 'dawnkeeper') final = Math.round(final * 1.2);
    const before = target.hp;
    target.hp = Math.min(target.maxHp, target.hp + final);
    const healed = target.hp - before;
    if (healed > 0) {
      this.cb.onFx?.({ type: 'heal', uid: target.uid, amount: healed, source: sourceName });
      this.addLog(`${target.name} <b>+${healed}</b> 회복`, 'heal');
    }
    return healed;
  }

  applyStatus(target, status, source) {
    if (!target?.alive || !status?.id) return;
    if (status.chance != null && Math.random() > status.chance) return;
    let turns = status.turns || 1;
    if (target.trait === 'fade' && statusType(status.id) !== 'buff' && status.id !== 'shield') {
      turns = Math.max(1, turns - 1);
    }
    const existing = target.statuses.find((s) => s.id === status.id);
    if (existing) {
      existing.turns = Math.max(existing.turns, turns);
      if (status.id === 'shield') {
        existing.amount = (existing.amount || 0) + Math.round(target.maxHp * (status.value || 0));
        existing.value = Math.max(existing.value || 0, status.value || 0);
      } else {
        existing.value = Math.max(existing.value || 0, status.value || 0);
      }
      if (status.source) existing.source = status.source;
    } else {
      const entry = { id: status.id, turns, value: status.value || 0, source: status.source || null };
      if (status.id === 'shield') entry.amount = Math.round(target.maxHp * (status.value || 0));
      target.statuses.push(entry);
    }
    this.cb.onFx?.({ type: 'status', uid: target.uid, text: statusName(status.id), statusId: status.id });
    this.addLog(`${target.name} · ${statusName(status.id)}`, 'status');
  }

  cleanse(target, count = 1) {
    const debuffs = target.statuses.filter((s) => ['debuff', 'control', 'dot'].includes(statusType(s.id)));
    const remove = debuffs.slice(0, count);
    for (const s of remove) {
      target.statuses = target.statuses.filter((x) => x !== s);
      this.addLog(`${target.name} · ${statusName(s.id)} 정화`, 'heal');
    }
    if (remove.length) this.cb.onFx?.({ type: 'cleanse', uid: target.uid });
  }

  dispel(target) {
    const buffs = target.statuses.filter((s) => statusType(s.id) === 'buff' || s.id === 'shield');
    for (const s of buffs) {
      target.statuses = target.statuses.filter((x) => x !== s);
      this.addLog(`${target.name} · ${statusName(s.id)} 해제`, 'system');
    }
    if (buffs.length) this.cb.onFx?.({ type: 'dispel', uid: target.uid });
  }

  // -------------------------------------------------------------------------
  // Enemy AI / auto ally
  // -------------------------------------------------------------------------

  enemyTurn(unit) {
    if (this.finished || !unit.alive) return;
    if (this.phase !== 'enemy') return;
    const abilities = (unit.abilities || []).filter((a) => (unit.cooldowns[a.name] || 0) <= 0);
    let action = null;
    if (abilities.length && Math.random() < 0.58) {
      action = pick(abilities);
      action = {
        ...action,
        id: action.name,
        icon: '✦',
        cooldown: action.cooldown || 0,
        target: action.target || (action.kind === 'heal' ? 'ally' : 'enemy'),
        kind: action.kind || 'physical',
        power: action.power || 1,
        reach: action.reach || (action.kind === 'physical' ? 'front' : 'any')
      };
      unit.cooldowns[action.name] = action.cooldown || 0;
    } else {
      action = {
        id: 'basic',
        name: '공격',
        icon: '⚔',
        kind: unit.attackKind,
        power: 1,
        reach: unit.attackReach,
        target: 'enemy',
        cost: 0,
        cooldown: 0
      };
    }
    const taunt = unit.statuses.find((s) => s.id === 'taunt' && s.source);
    let targetUid = null;
    if (taunt) {
      const taunter = this.getUnit(taunt.source);
      if (taunter?.alive) targetUid = taunter.uid;
    }
    if (!targetUid) {
      const targets = this.getValidTargets(unit, action);
      if (targets.length) {
        const sorted = [...targets].sort((a, b) => a.hp / a.maxHp - b.hp / b.maxHp);
        targetUid = (Math.random() < 0.55 ? sorted[0] : pick(targets)).uid;
      }
    }
    this.executeAction(unit, action, targetUid);
  }

  autoAlly(unit) {
    if (!unit || !unit.alive || this.phase !== 'select') return;
    const actions = this.getPlayerActions().filter((a) => !a.disabled && a.id !== 'potion' && a.id !== 'ether');
    const kit = actions.find((a) => a.id === unit.kitAbility?.id);
    const ability = actions.find((a) => a.id === unit.ability?.id);
    const targetTypes = [kit, ability].filter(Boolean);
    for (const action of targetTypes) {
      if (action.target === 'allAllies' || action.target === 'ally' || action.target === 'self') {
        this.executeAction(unit, action, null);
        return;
      }
      if (Math.random() < 0.45) {
        const targets = this.getValidTargets(unit, action);
        if (targets.length) {
          this.executeAction(unit, action, pick(targets).uid);
          return;
        }
      }
    }
    const enemies = this.getAlive('enemy');
    if (!enemies.length) return;
    const sorted = [...enemies].sort((a, b) => a.hp - b.hp);
    this.executeAction(unit, actions[0], sorted[0].uid);
  }

  getState() {
    const active = this.getActive();
    return {
      round: this.round,
      phase: this.phase,
      activeUid: this.activeUid,
      queue: [...this.queue],
      units: this.units,
      actions: this.getPlayerActions(),
      pendingAction: this.pendingAction,
      validTargets: this.phase === 'target' && this.pendingAction ? this.getValidTargets(active, this.pendingAction).map((u) => u.uid) : [],
      message: this.message,
      items: { ...this.items },
      auto: this.auto,
      finished: this.finished,
      result: this.result
    };
  }
}

