  } else if (app.step === 1) {
    if (!cls) {
      host.innerHTML = `<div class="detail-head"><div><h3>클래스를 고르세요</h3><p>BASE CLASS</p></div></div>
        <div class="detail-section"><p class="detail-desc">각 기본 클래스는 고유 능력과 장비 범주를 가집니다. 아래에서 역할 · 무기 · 방어구 · 주요 능력치 · 고유 능력을 비교하세요.</p></div>`;
